class RefusedSendHonestyTest(unittest.TestCase):
    """What a refused send tells its sender about what the peer will still see.

    A refusal born in the transport leaves the words nowhere the peer can read
    them. Measured on this project's own records, both `reply_to_codex` and
    `antiphon_send` reach the peer's page as a bare tool-name line; their text
    arguments remain unreachable by either parser. So those refusals name the
    road that does carry words — the visible reply, which travels with the
    passive pages, in order and in full.

    An addressing refusal already names its own fix and says nothing more. That
    is structural rather than a matter of discipline: only the guidance-carrying
    birth sites wrap their detail in a class, and a detail carrying none is
    handed back untouched. `push` reads no class at all — its failure print goes
    to stderr on an exit-0 hook, which this file records as reaching a debug log
    and not the agent, so a second-person sentence there is addressed to nobody.
    """

    UUID = "1d5a03e0-0548-4339-87c3-45c5dbf7e9d7"
    OTHER = "2e6b14f1-1659-544a-98d4-56d6eca8fa48"

    # The host refusal this work was opened on, observed twice in one session.
    HOST_ERROR = ("direct app-server input is not allowed for unloaded "
                  "spawned sub-agents")
    NO_SESSION = "not delivered: no Codex session found in this directory"

    @staticmethod
    def _codex_peer(project, alias, owner, session=None):
        antiphon.peers.register(project, "codex", alias, None,
                                pid=os.getpid(), owner_key=owner)
        if session:
            antiphon.peers.write_session(project, "codex", alias, session,
                                         f"/t/{alias}.jsonl", owner)

    @staticmethod
    def _reply(project, payload):
        out, err = io.StringIO(), io.StringIO()
        with patch.object(antiphon, "project_dir", return_value=project), \
             patch.object(antiphon.sys, "stdin", io.StringIO(json.dumps(payload))), \
             contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            code = antiphon.reply()
        return code, out.getvalue(), err.getvalue()

    @staticmethod
    def _push(project, target, turn_text, extra=()):
        """One Stop-hook push of `turn_text`, with its stderr captured."""
        payload = {"cwd": project, "transcript_path": "/tmp/transcript"}
        turn = "_claude_turn" if target == "codex" else "_codex_turn"
        err = io.StringIO()
        with contextlib.ExitStack() as stack:
            enter = stack.enter_context
            enter(patch.object(antiphon.os.path, "exists", return_value=True))
            enter(patch.object(antiphon, turn, return_value=(turn_text, "")))
            enter(patch.object(antiphon, "read_cursor", return_value={}))
            enter(patch.object(antiphon, "write_cursor", return_value=True))
            enter(patch.object(antiphon.sys, "stdin",
                               io.StringIO(json.dumps(payload))))
            enter(contextlib.redirect_stderr(err))
            for context in extra:
                enter(context)
            code = antiphon.push(target)
        return code, err.getvalue()

    class _Refused:
        """`codex queue` answering with a non-zero return and a reason."""

        returncode = 1
        stdout = ""

        def __init__(self, stderr):
            self.stderr = stderr

    class _Queued:
        returncode = 0
        stderr = ""
        stdout = ""

    class _DeadSocket:
        """A connect refused with an errno the sender does not wait out.

        `ENOENT` and `ECONNREFUSED` are retried for `CONNECT_PATIENCE` because a
        channel about to exist looks exactly like one that never will. This is a
        real outage instead, and fails at once.
        """

        def __call__(self, *_a, **_k):
            return self

        def settimeout(self, _):
            pass

        def close(self):
            pass

        def connect(self, _path):
            raise OSError(errno.EACCES, "Permission denied")

    class _LiveSocket:
        """A channel that connects. What happens after that is the fixture.

        `answer` is what the server sends back; `breaks` is raised once the
        bytes are already on their way, which is the one failure the sender must
        never retry.
        """

        def __init__(self, answer=b'{"ok": true, "message_id": "m1"}', breaks=None):
            self.answer = answer
            self.breaks = breaks

        def __call__(self, *_a, **_k):
            return self

        def __enter__(self):
            return self

        def __exit__(self, *_a):
            return False

        def settimeout(self, _):
            pass

        def close(self):
            pass

        def connect(self, _path):
            pass

        def sendall(self, _data):
            if self.breaks is not None:
                raise self.breaks

        def shutdown(self, _how):
            pass

        def recv(self, _n):
            answer, self.answer = self.answer, b""
            return answer

    def _oversized(self):
        """Larger than any store will hold, so it still refuses.

        Between `MAX_CHANNEL_BYTES` and `ATTACHMENT_MAX` an oversized direct
        send now parks its words and delivers an envelope, so a fixture there
        would exercise the spill instead of the refusal these cases are about.
        Above `ATTACHMENT_MAX` there is no store road, the send falls through
        to the same `oversize` refusal it always made, and every assertion here
        keeps its meaning. Measured at 11 ms to build and serialize one of
        these, which is why the move is cheaper than rewriting the cases.
        """
        return "x" * (antiphon.ATTACHMENT_MAX + 10)

    # ---- the guidance-carrying classes ----

    def test_a_refused_reply_names_the_passive_page(self):
        """The host refused the queue: nothing of these words is on the page but
        the tool's name, and the sender is told where they would travel."""
        with tempfile.TemporaryDirectory() as project:
            self._codex_peer(project, "build", "300:build", self.UUID)
            with patch.object(antiphon.subprocess, "run",
                              return_value=self._Refused(self.HOST_ERROR)):
                code, out, err = self._reply(project, {"text": "hi", "to": "build"})
        self.assertEqual(code, 1)
        self.assertEqual(out, "")
        self.assertEqual(err, "reply: {} — {}\n".format(
            self.HOST_ERROR,
            antiphon.TOOL_GUIDANCE.format(seen="only a tool-name line")))

    def test_a_refused_send_tool_names_the_passive_page(self):
        """Claude's page gets the real call name, but never its message input."""
        with tempfile.TemporaryDirectory() as project:
            antiphon.peers.register(project, "claude", "ui", "/tmp/ui.sock")
            with patch.object(antiphon.socket, "socket", self._DeadSocket()):
                result = antiphon._send_tool(project, "hi", "ui")
        self.assertIs(result.get("isError"), True)
        self.assertEqual(result["content"][0]["text"],
                         "Not delivered to Claude: Claude MCP Channel is down: "
                         "Permission denied — "
                         + antiphon.TOOL_GUIDANCE.format(
                             seen="only a tool-name line"))

    def test_a_missing_codex_session_still_gets_the_guidance(self):
        """Discovery finding no rollout to address says nothing about a peer's
        ability to read: the Codex-side page is built from *Claude's*
        transcripts and carries these words regardless — measured in the same
        fixture that produces this refusal."""
        with tempfile.TemporaryDirectory() as project, \
             patch.object(antiphon, "codex_session_id", return_value=(None, None)):
            code, _, err = self._reply(project, {"text": "hi"})
        self.assertEqual(code, 1)
        self.assertEqual(err, "reply: {} — {}\n".format(
            self.NO_SESSION,
            antiphon.TOOL_GUIDANCE.format(seen="only a tool-name line")))

    def test_an_oversized_direct_send_names_the_paged_road(self):
        """Refused before the socket is touched, and the visible reply is
        exactly where an oversized text still travels whole: the automatic hook
        hands an oversized record over without splitting it."""
        with tempfile.TemporaryDirectory() as project:
            antiphon.peers.register(project, "claude", "ui", "/tmp/ui.sock")
            with patch.object(antiphon.socket, "socket") as opened:
                result = antiphon._send_tool(project, self._oversized(), "ui")
                opened.assert_not_called()
        text = result["content"][0]["text"]
        self.assertIs(result.get("isError"), True)
        self.assertIn("the channel accepts at most {}".format(
            antiphon.MAX_CHANNEL_BYTES), text)
        self.assertTrue(
            text.endswith(" — " + antiphon.TOOL_GUIDANCE.format(
                seen="only a tool-name line")),
            text)

    def test_every_wrap_site_reaches_its_reader_with_the_guidance(self):
        """One case per birth site that wraps, driven through the reader.

        The tests above pin a *class*, and several sites share a class — so with
        only those, a single wrap could be deleted and nothing would notice.
        Measured: four of the ten could go one at a time with the whole suite
        still green. A class is not a gate; a site is. A new wrap needs a new
        case here, which the count assertion below insists on.
        """
        replied = antiphon.TOOL_GUIDANCE.format(seen="only a tool-name line")
        sent = antiphon.TOOL_GUIDANCE.format(seen="only a tool-name line")

        def named_reply(*contexts):
            """`reply()` to a peer that resolves, so the transport is reached."""
            with tempfile.TemporaryDirectory() as project:
                self._codex_peer(project, "build", "300:build", self.UUID)
                with contextlib.ExitStack() as stack:
                    for context in contexts:
                        stack.enter_context(context)
                    return self._reply(project, {"text": "hi", "to": "build"})[2]

        def bare_reply(*contexts):
            """`reply()` with nothing registered: the unnamed single pair."""
            with tempfile.TemporaryDirectory() as project, \
                 contextlib.ExitStack() as stack:
                for context in contexts:
                    stack.enter_context(context)
                return self._reply(project, {"text": "hi"})[2]

        def send(*contexts, text="hi"):
            with tempfile.TemporaryDirectory() as project:
                antiphon.peers.register(project, "claude", "ui", "/tmp/ui.sock")
                with contextlib.ExitStack() as stack:
                    for context in contexts:
                        stack.enter_context(context)
                    result = antiphon._send_tool(project, text, "ui")
            return result["content"][0]["text"]

        def bare_send(*contexts):
            with tempfile.TemporaryDirectory() as project, \
                 contextlib.ExitStack() as stack:
                stack.enter_context(patch.object(antiphon, "CONNECT_PATIENCE", 0))
                for context in contexts:
                    stack.enter_context(context)
                result = antiphon._send_tool(project, "hi")
            return result["content"][0]["text"]

        def channel(**how):
            return patch.object(antiphon.socket, "socket",
                                self._LiveSocket(**how))

        sites = [
            ("_queue_codex: the codex command is missing",
             lambda: named_reply(patch.object(antiphon.subprocess, "run",
                                              side_effect=FileNotFoundError())),
             "codex command not found", replied),
            ("_queue_codex: the exec itself was refused",
             lambda: named_reply(patch.object(
                 antiphon.subprocess, "run",
                 side_effect=OSError(errno.E2BIG, "Argument list too long"))),
             "Argument list too long", replied),
            ("_queue_codex: the subprocess never completed",
             lambda: named_reply(patch.object(
                 antiphon.subprocess, "run",
                 side_effect=subprocess.TimeoutExpired("codex", 15))),
             "TimeoutExpired", replied),
            ("_queue_codex: the host refused the queue",
             lambda: named_reply(patch.object(
                 antiphon.subprocess, "run",
                 return_value=self._Refused(self.HOST_ERROR))),
             self.HOST_ERROR, replied),
            ("_legacy_target: discovery found no Codex rollout",
             lambda: bare_reply(patch.object(antiphon, "codex_session_id",
                                             return_value=(None, None))),
             self.NO_SESSION, replied),
            ("send_to_claude: over the channel's byte cap",
             lambda: send(text=self._oversized()),
             "the channel accepts at most", sent),
            ("send_to_claude: the connect was refused",
             lambda: send(patch.object(antiphon.socket, "socket",
                                       self._DeadSocket())),
             "Channel is down: Permission denied", sent),
            ("send_to_claude: no registry and no legacy channel",
             lambda: bare_send(patch.object(
                 antiphon.socket, "socket",
                 side_effect=FileNotFoundError(errno.ENOENT,
                                               "No such file or directory"))),
             "no Claude peer is registered", sent),
            ("send_to_claude: it broke after the bytes went out",
             lambda: send(channel(breaks=OSError(errno.EPIPE, "Broken pipe"))),
             "Channel is down: Broken pipe", sent),
            ("send_to_claude: the answer did not decode",
             lambda: send(channel(answer=b"not json at all")),
             "invalid response", sent),
            ("send_to_claude: the answer decoded to something that is not one",
             lambda: send(channel(answer=b"[]")),
             "invalid response", sent),
            ("send_to_claude: the channel server itself said no",
             lambda: send(channel(
                 answer=b'{"ok": false, "error": "channel said no"}')),
             "channel said no", sent),
        ]
        # 10 original rows plus `_queue_codex`'s crash-belt and the bare
        # channel's honest `no-peer` refusal. The former turns
        # an exec the kernel refuses — measured at 1.1 MB of message on this
        # machine — into a classified refusal instead of a traceback out of a
        # Stop hook. The quota refusal born in the spill branch adds no row: it
        # is unclassed, and an unwrapped refusal is not a census site.
        self.assertEqual(len(sites), 12,
                         "one case per wrap site, and every wrap site has one")
        for label, refuse, fragment, guidance in sites:
            with self.subTest(label):
                said = refuse().rstrip("\n")
                self.assertIn(fragment, said, "the fixture missed its site")
                self.assertTrue(said.endswith(" — " + guidance), said)

    # ---- everything else holds still ----

    def test_an_addressing_refusal_stays_byte_identical(self):
        """One representative per addressing shape per direction, against the
        recorded dry runs. These messages already name the fix, and the marker
        advice would be worse than what they say: an unaddressed `@codex` line
        is refused identically, and `@codex:name` needs exactly the name whose
        absence caused the refusal."""
        with tempfile.TemporaryDirectory() as project:
            self._codex_peer(project, "build", "300:build", self.UUID)
            self._codex_peer(project, "review", "301:review", self.OTHER)
            ambiguous = self._reply(project, {"text": "hi"})
            unknown = self._reply(project, {"text": "hi", "to": "nobody-here"})
            unusable = self._reply(project, {"text": "hi", "to": "not a name"})
            # Caller-supplied recipient text is never reproduced in the
            # refusal. A classifier still receives an explicit refusal class,
            # rather than inferring one from either user text or prose.
            impostor = self._reply(project, {
                "text": "hi", "to": self.NO_SESSION.split(": ", 1)[1]})
        self.assertEqual(ambiguous, (1, "", (
            "reply: not delivered: 2 codex peers are live "
            "(build: ready, review: ready); address one by name\n")))
        self.assertEqual(unknown, (1, "", (
            "reply: not delivered: no live codex peer named 'nobody-here'; "
            "live peers: build, review\n")))
        self.assertEqual(unusable, (1, "", (
            "reply: not delivered: the supplied recipient is not a usable peer name; "
            "live codex peers: build, review\n")))
        self.assertEqual(impostor, (1, "", (
            "reply: not delivered: the supplied recipient is not a usable peer "
            "name; live codex peers: build, review\n")))

        with tempfile.TemporaryDirectory() as project:
            self._codex_peer(project, "build", "300:build")     # no session yet
            waiting = self._reply(project, {"text": "hi", "to": "build"})
        self.assertEqual(waiting, (1, "", (
            "reply: not delivered: 'build' is live but not yet routable — "
            "it has not run a turn yet\n")))

        with tempfile.TemporaryDirectory() as project:
            self._codex_peer(project, "build", "300:build", self.UUID)
            lone = self._reply(project, {"text": "hi"})
        self.assertEqual(lone, (1, "", (
            "reply: not delivered: build: ready is the only registered Codex "
            "peer, but unnamed Codex sessions are not all observable and cannot "
            "be ruled out — address a peer by name\n")))

        # The Claude direction. `not yet routable` has no representative here:
        # `read_peers` skips an addressless Claude record, so that shape is
        # Codex-only, and `unknown peer kind` is unreachable: both callers of
        # `resolve_target` pass a literal kind.
        # A valid name nobody answers to is retried while the peer might still
        # be registering; the patience is cut to nothing so the suite does not
        # wait out a decision that has already been made.
        with tempfile.TemporaryDirectory() as project, \
             patch.object(antiphon, "CONNECT_PATIENCE", 0):
            antiphon.peers.register(project, "claude", "ui", "/tmp/ui.sock")
            antiphon.peers.register(project, "claude", "api", "/tmp/api.sock")
            said = [antiphon._send_tool(project, "hi"),
                    antiphon._send_tool(project, "hi", "nobody-here"),
                    antiphon._send_tool(project, "hi", "not a name")]
        self.assertEqual([r["content"][0]["text"] for r in said], [
            "Not delivered to Claude: not delivered: 2 claude peers are live "
            "(api: ready, ui: ready); address one by name",
            "Not delivered to Claude: not delivered: no live claude peer named "
            "'nobody-here'; live peers: api, ui",
            "Not delivered to Claude: not delivered: the supplied recipient is "
            "not a usable peer name; live claude peers: api, ui",
        ])
        self.assertTrue(all(r.get("isError") for r in said))

    def test_a_failed_push_stays_byte_identical(self):
        """Push renders no guidance, in either direction and for every class —
        including the classes that are wrapped and flow through it. Its stderr
        is printed on an exit-0 hook, which this codebase measured as reaching a
        debug log and nothing else."""
        with tempfile.TemporaryDirectory() as project:
            self._codex_peer(project, "build", "300:build", self.UUID)
            transport = self._push(
                project, "codex", "@codex:build ship it",
                [patch.object(antiphon.subprocess, "run",
                              return_value=self._Refused(self.HOST_ERROR))])
        self.assertEqual(transport, (0, "antiphon: delivery failed — {}\n".format(
            self.HOST_ERROR)))

        with tempfile.TemporaryDirectory() as project:
            no_peer = self._push(
                project, "codex", "@codex ship it",
                [patch.object(antiphon, "codex_session_id", return_value=(None, None))])
        self.assertEqual(no_peer, (0, "antiphon: delivery failed — {}\n".format(
            self.NO_SESSION)))

        with tempfile.TemporaryDirectory() as project:
            self._codex_peer(project, "build", "300:build", self.UUID)
            self._codex_peer(project, "review", "301:review", self.OTHER)
            addressing = self._push(project, "codex", "@codex ship it")
        self.assertEqual(addressing, (0, (
            "antiphon: delivery failed — not delivered: 2 codex peers are live "
            "(build: ready, review: ready); address one by name\n")))

        with tempfile.TemporaryDirectory() as project:
            antiphon.peers.register(project, "claude", "ui", "/tmp/ui.sock")
            down = self._push(project, "claude", "@claude:ui landed",
                              [patch.object(antiphon.socket, "socket",
                                            self._DeadSocket())])
        self.assertEqual(down, (0, (
            "antiphon: delivery failed — Claude MCP Channel is down: "
            "Permission denied\n")))

        with tempfile.TemporaryDirectory() as project:
            antiphon.peers.register(project, "claude", "ui", "/tmp/ui.sock")
            antiphon.peers.register(project, "claude", "api", "/tmp/api.sock")
            unaddressed = self._push(project, "claude", "@claude landed")
        self.assertEqual(unaddressed, (0, (
            "antiphon: delivery failed — not delivered: 2 claude peers are live "
            "(api: ready, ui: ready); address one by name\n")))

        # The one class whose byte count depends on the payload envelope, so it
        # is pinned by both ends of the line rather than by the whole of it.
        with tempfile.TemporaryDirectory() as project:
            antiphon.peers.register(project, "claude", "ui", "/tmp/ui.sock")
            code, oversize = self._push(project, "claude",
                                        "@claude:ui " + self._oversized())
        self.assertEqual(code, 0)
        self.assertTrue(oversize.startswith(
            "antiphon: delivery failed — message is "), oversize)
        self.assertTrue(oversize.endswith(
            "bytes; the channel accepts at most {}\n".format(
                antiphon.MAX_CHANNEL_BYTES)), oversize)

        for _, printed in (transport, no_peer, addressing, down, unaddressed):
            self.assertNotIn("passive pages", printed)
        self.assertNotIn("passive pages", oversize)

    def test_a_successful_send_stays_quiet(self):
        """A delivered message says what it always said, plus the id its
        receipt will show. `reply()` writes one JSON line for the channel
        server on stdout and nothing on stderr — the pin there is on the
        empty string."""
        with tempfile.TemporaryDirectory() as project:
            self._codex_peer(project, "build", "300:build", self.UUID)
            with patch.object(antiphon.subprocess, "run",
                              return_value=self._Queued()):
                code, out, err = self._reply(project, {"text": "hi", "to": "build"})
        self.assertEqual((code, err), (0, ""))
        self.assertEqual(json.loads(out)["queued"], True)

        with tempfile.TemporaryDirectory() as project:
            antiphon.peers.register(project, "claude", "ui", "/tmp/ui.sock")
            with patch.object(antiphon.socket, "socket", self._LiveSocket()):
                named = antiphon._send_tool(project, "hi", "ui")
        self.assertRegex(named["content"][0]["text"],
                         r"^Delivered to the Claude Code peer 'ui' \(id [0-9a-f-]{36}\); "
                         r"antiphon status shows when Claude's transcript received it\.$")

        with tempfile.TemporaryDirectory() as project:
            with patch.object(antiphon.socket, "socket", self._LiveSocket()):
                bare = antiphon._send_tool(project, "hi")
        self.assertRegex(bare["content"][0]["text"],
                         r"^Delivered to the Claude Code channel \(id [0-9a-f-]{36}\); ")

    def test_an_oversized_multiline_stop_is_refused_and_never_parked(self):
        body = self._oversized()
        with tempfile.TemporaryDirectory() as project:
            antiphon.peers.register(project, "claude", "ui", "/tmp/ui.sock")
            code, printed = self._push(
                project, "claude", "@claude:ui <<BIG\n" + body + "\nBIG")
            store = os.path.join(project, ".antiphon", "messages")
            self.assertFalse(os.path.exists(store),
                             "the marker road must not create an attachment")
        self.assertEqual(code, 0)
        self.assertIn("delivery failed — message is", printed)
        self.assertIn(str(antiphon.MAX_CHANNEL_BYTES), printed)
        self.assertNotIn(antiphon.ATTACHMENT_LABEL, printed)

    def test_the_guidance_fits_the_channel_slice(self):
        """`channel.mjs` hands the calling agent `detail.slice(0, 500)` of
        Python's whole stderr line, which `reply()` writes as `reply: <detail>`.
        The longest guidance-carrying detail is a host refusal, which
        `_queue_codex` cuts at 200 characters — `no-peer` (54) and `oversize`
        are both shorter — so 396 of 500 is the worst case, and the 104
        characters of headroom are what let `channel.mjs` stay untouched.

        Measured end to end rather than assembled from literals: a host that
        answers with far more than the cut still produces this line.
        """
        with tempfile.TemporaryDirectory() as project:
            self._codex_peer(project, "build", "300:build", self.UUID)
            with patch.object(antiphon.subprocess, "run",
                              return_value=self._Refused("h" * 500)):
                _, _, err = self._reply(project, {"text": "hi", "to": "build"})
        line = err.strip()          # `channel.mjs` trims before it slices
        self.assertEqual(len(line), 396)
        self.assertLess(len(line), 500)
        self.assertTrue(line.endswith(antiphon.TOOL_GUIDANCE.format(
            seen="only a tool-name line")), line)


class AttachmentSpillTest(unittest.TestCase):
    """An oversized direct message parks its words instead of dying.

    The decision lives in the tools, above the transports: measured, a spill
    inside `send_to_claude` or `_queue_codex` strips the bridge prefix the echo
    guard is anchored on, and leaves the mid-turn park holding the original. At
    this layer the envelope simply replaces the outgoing text, and prefixes,
    labels, the park and dedupe all see an ordinary message.

    The fakes are bounded on purpose. A bare `MagicMock` socket satisfies
    `connect`/`sendall`/`shutdown` and then hands `send_to_claude`'s reply loop
    a truthy mock whose `__len__` is 0 — an infinite loop, measured as two
    suite hangs in exactly this area.
    """

    UUID = RefusedSendHonestyTest.UUID
    _DeadSocket = RefusedSendHonestyTest._DeadSocket
    _LiveSocket = RefusedSendHonestyTest._LiveSocket
    _Refused = RefusedSendHonestyTest._Refused
    _Queued = RefusedSendHonestyTest._Queued

    # Measured against `send_to_claude`'s own serialization (Task 1(b)): raw
    # 130,982 bytes serialize to 131,073 — one byte over a cap the raw length
    # is 90 bytes under. A trigger on `len(text.encode())` lets this through.
    ASCII_BAND = "x" * 130_982
    # Six-fold escaping: every control character costs `\u00XX`. Raw 22,000,
    # serialized 132,091 — one sixth of the cap by raw bytes and over it by
    # payload bytes.
    HIGH_ESCAPE = "\x01" * 22_000

    class _Recorder(RefusedSendHonestyTest._LiveSocket):
        """A channel that connects, answers, and keeps what it was handed."""

        def __init__(self, **how):
            super().__init__(**how)
            self.payloads = []

        def sendall(self, data):
            self.payloads.append(data)
            super().sendall(data)

    @staticmethod
    def _codex_peer(project, alias, owner, session=None):
        RefusedSendHonestyTest._codex_peer(project, alias, owner, session)

    @staticmethod
    def _reply(project, payload):
        return RefusedSendHonestyTest._reply(project, payload)

    @staticmethod
    def _store(project):
        return os.path.join(project, ".antiphon", "messages")

    @classmethod
    def _files(cls, project):
        """Every entry in the store, by name — foreign ones included."""
        store = cls._store(project)
        return sorted(os.listdir(store)) if os.path.isdir(store) else []

    @classmethod
    def _only_parked(cls, project):
        """The one parked attachment, as (absolute path, content bytes)."""
        names = cls._files(project)
        assert len(names) == 1, names
        path = os.path.join(cls._store(project), names[0])
        with open(path, "rb") as f:
            return path, f.read().partition(b"\n\n")[2]

    @staticmethod
    def _queue_recorder(queued):
        """`codex queue` that accepts, and keeps the argv it was exec'd with.

        Everything else runs for real. The registry's own `ps` liveness probe
        shares this module attribute — measured, it is the first call through
        here — and answering it with a queue fixture would quietly make every
        peer look however the fixture looks.
        """
        real = antiphon.subprocess.run

        def run(argv, **kw):
            if list(argv[:2]) != ["codex", "queue"]:
                return real(argv, **kw)
            queued.append(argv)
            return RefusedSendHonestyTest._Queued()
        return patch.object(antiphon.subprocess, "run", side_effect=run)

    @staticmethod
    def _spills_over(size):
        """The queue predicate, patched down to `size` bytes.

        The real bound is computed at call time from `SC_ARG_MAX` minus the
        live environment, so it moves between machines and between shells —
        measured at 1,044,907 / 844,907 / 444,907 bytes as the environment
        grew. Building a payload over it in a test would be both slow and
        wrong; the predicate is the seam, and it is the thing patched.
        """
        return patch.object(antiphon, "_oversized_for_queue",
                            side_effect=lambda message: len(message) > size)

    @staticmethod
    def _push_live(project, target, turn_text):
        """One Stop-hook push against the project's REAL cursor.

        `RefusedSendHonestyTest._push` patches the cursor away, which is right
        for a refusal fixture and wrong here: the question this arm asks is
        what the park written a moment ago does to the echo.
        """
        transcript = os.path.join(project, "transcript.jsonl")
        with open(transcript, "w", encoding="utf-8"):
            pass
        payload = {"cwd": project, "transcript_path": transcript}
        turn = "_claude_turn" if target == "codex" else "_codex_turn"
        err = io.StringIO()
        with patch.object(antiphon, turn, return_value=(turn_text, "")), \
             patch.object(antiphon.sys, "stdin",
                          io.StringIO(json.dumps(payload))), \
             contextlib.redirect_stderr(err):
            code = antiphon.push(target)
        return code, err.getvalue()

    def test_an_oversized_claude_send_parks_and_envelopes(self):
        """Both measured shapes trigger on the SERIALIZED size, the file holds
        its own provenance, and the socket is handed only the envelope."""
        for shape, text in (("the ascii band", self.ASCII_BAND),
                            ("six-fold escaping", self.HIGH_ESCAPE)):
            with self.subTest(shape), tempfile.TemporaryDirectory() as project:
                antiphon.peers.register(project, "claude", "ui", "/tmp/ui.sock")
                channel = self._Recorder()
                with patch.object(antiphon.socket, "socket", channel):
                    result = antiphon._send_tool(project, text, "ui")
                self.assertIsNot(result.get("isError"), True, result)

                names = self._files(project)
                self.assertEqual(len(names), 1, names)
                self.assertRegex(names[0], antiphon.ATTACHMENT_NAME)
                path, content = self._only_parked(project)
                self.assertEqual(os.stat(path).st_mode & 0o777, 0o600)
                self.assertEqual(
                    os.stat(self._store(project)).st_mode & 0o777, 0o700)

                with open(path, "rb") as f:
                    header = f.read().partition(b"\n\n")[0]
                self.assertNotIn(b"\n", header, "one header line, then a blank")
                self.assertEqual(content, text.encode(), "the content is exact")
                digest = hashlib.sha256(content).hexdigest()
                self.assertIn(b"[Antiphon attachment from=", header)
                self.assertIn(f"sha256={digest}".encode(), header)
                self.assertIn(f"bytes={len(content)}".encode(), header)

                self.assertEqual(len(channel.payloads), 1)
                envelope = json.loads(channel.payloads[0].decode())["content"]
                self.assertIn(digest, envelope)
                self.assertIn(path, envelope)
                self.assertIn(str(len(content)), envelope)
                self.assertNotIn(text[:400], envelope)
                self.assertLess(len(channel.payloads[0]), 2_000,
                                "the transport carried the envelope, not the "
                                "words it stands for")
                said = result["content"][0]["text"]
                self.assertIn(path, said, "the sender is told where its words "
                                          "went")
                self.assertIn(str(len(content)), said)

    def test_an_oversized_queue_send_parks_and_envelopes(self):
        """The Claude->Codex mirror, above the runtime queue bound, and the
        crash-belt underneath it."""
        text = "y" * 4_000
        with tempfile.TemporaryDirectory() as project:
            self._codex_peer(project, "build", "300:build", self.UUID)
            queued = []
            with self._spills_over(500), self._queue_recorder(queued):
                code, out, err = self._reply(project, {"text": text,
                                                       "to": "build"})
            self.assertEqual(code, 0, err)
            self.assertEqual(err, "")
            self.assertRegex(json.loads(out)["attachment"],
                             r"^[0-9a-f-]{36}\.txt$",
                             "the caller learns the parked file's name")
            path, content = self._only_parked(project)
            self.assertEqual(content, text.encode())
            self.assertEqual(len(queued), 1)
            message = queued[0][-1]
            self.assertTrue(
                message.startswith(antiphon.CHANNEL_LABEL + " [from="), message)
            self.assertIn(antiphon.ATTACHMENT_LABEL, message)
            self.assertIn(path, message)
            self.assertNotIn(text[:400], message)
            self.assertLess(len(message.encode()), 2_000)

        # The belt, with the predicate never firing: the exec itself is refused
        # and the old uncaught OSError becomes a classified refusal. No payload
        # is built for this — the failure is the seam.
        with tempfile.TemporaryDirectory() as project:
            self._codex_peer(project, "build", "300:build", self.UUID)
            with patch.object(antiphon, "_oversized_for_queue",
                              return_value=False), \
                 patch.object(antiphon.subprocess, "run",
                              side_effect=OSError(errno.E2BIG,
                                                  "Argument list too long")):
                code, out, err = self._reply(project, {"text": "hi",
                                                       "to": "build"})
            self.assertEqual((code, out), (1, ""))
            self.assertIn("Argument list too long", err)
            self.assertTrue(err.strip().endswith(antiphon.TOOL_GUIDANCE.format(
                seen="only a tool-name line")), err)
            self.assertEqual(self._files(project), [])

    def test_a_refused_send_leaves_no_file(self):
        """Write, send, and on any non-delivery unlink at once with a word.

        A refusal never charges the store: an agent retrying an oversized send
        against a down channel would otherwise write one full-size orphan per
        attempt and convert a transport outage into a permanent storage
        refusal.
        """
        with tempfile.TemporaryDirectory() as project:
            antiphon.peers.register(project, "claude", "ui", "/tmp/ui.sock")
            err = io.StringIO()
            with patch.object(antiphon.socket, "socket", self._DeadSocket()), \
                 contextlib.redirect_stderr(err):
                result = antiphon._send_tool(project, self.ASCII_BAND, "ui")
            self.assertIs(result.get("isError"), True)
            self.assertEqual(self._files(project), [],
                             "a refused send must not charge the store")
            self.assertIn("attachment", err.getvalue().lower())

        with tempfile.TemporaryDirectory() as project:
            self._codex_peer(project, "build", "300:build", self.UUID)
            with self._spills_over(500), \
                 patch.object(antiphon.subprocess, "run",
                              return_value=self._Refused("host said no")):
                code, _out, err = self._reply(project, {"text": "y" * 4_000,
                                                        "to": "build"})
            self.assertEqual(code, 1)
            self.assertEqual(self._files(project), [])
            self.assertIn("attachment", err.lower())

    def test_the_park_holds_the_envelope(self):
        """The park takes the BARE envelope — what `deliver_batches` compares —
        on both tool arms, and the original text enters no fingerprint."""
        with tempfile.TemporaryDirectory() as project:
            antiphon.peers.register(project, "claude", "ui", "/tmp/ui.sock")
            channel = self._Recorder()
            with patch.object(antiphon.socket, "socket", channel):
                antiphon._send_tool(project, self.ASCII_BAND, "ui")
            envelope = json.loads(channel.payloads[0].decode())["content"]
            park = antiphon.parked_deliveries(
                antiphon.read_cursor(project, "codex")["last_pushed_claude"])
            self.assertEqual(park["@ui"],
                             antiphon.batch_fingerprint([envelope]))
            self.assertNotEqual(park["@ui"], antiphon.batch_fingerprint(
                [self.ASCII_BAND]), "the original enters no fingerprint")

            # And the giant echo that ends the same turn is not suppressed by
            # that park — it is refused, by push's own unchanged oversize
            # behaviour, which `test_a_failed_push_stays_byte_identical` pins
            # byte for byte. The words still travel: the visible reply carries
            # them through the passive pages.
            code, printed = self._push_live(
                project, "claude", "@claude:ui " + self.ASCII_BAND)
            self.assertEqual(code, 0)
            self.assertTrue(printed.startswith(
                "antiphon: delivery failed — message is "), printed)
            self.assertTrue(printed.endswith(
                "bytes; the channel accepts at most {}\n".format(
                    antiphon.MAX_CHANNEL_BYTES)), printed)

        # `reply()` parks the bare text while it sends the composed one, and
        # the two differ by the measured 80-byte `CHANNEL_LABEL` + queue label.
        with tempfile.TemporaryDirectory() as project:
            self._codex_peer(project, "build", "300:build", self.UUID)
            queued = []
            with self._spills_over(500), self._queue_recorder(queued):
                self._reply(project, {"text": "y" * 4_000, "to": "build"})
            composed = queued[0][-1]
            bare = composed[composed.index(antiphon.ATTACHMENT_LABEL):]
            prefix = composed[:composed.index(antiphon.ATTACHMENT_LABEL)]
            self.assertRegex(prefix, r"^\[Antiphon channel\] Claude: "
                                     r"\[from=<unnamed> id=[0-9a-f-]{36}\] $")
            # 84 bytes for an unnamed sender, 80 for a short alias — measured
            # either way as a prefix the park must not hold.
            self.assertEqual(len(prefix), 84)
            park = antiphon.parked_deliveries(
                antiphon.read_cursor(project, "claude")["last_pushed_codex"])
            self.assertEqual(park["@build"], antiphon.batch_fingerprint([bare]))
            self.assertNotEqual(park["@build"],
                                antiphon.batch_fingerprint([composed]))
            self.assertNotEqual(park["@build"],
                                antiphon.batch_fingerprint(["y" * 4_000]))

    def test_above_the_attachment_cap_the_guidance_returns(self):
        """Over `ATTACHMENT_MAX` no store road is left, so the send falls
        through to the refusal that names the road that still carries words.

        This is where the two moved refused-send fixtures now live:
        `RefusedSendHonestyTest._oversized` and the inline `"ç"` fixture of
        `test_the_send_tool_reports_an_oversized_message_as_an_error` both sit
        above this cap, which is why they still refuse rather than spilling.
        """
        with tempfile.TemporaryDirectory() as project:
            antiphon.peers.register(project, "claude", "ui", "/tmp/ui.sock")
            with patch.object(antiphon.socket, "socket") as opened:
                result = antiphon._send_tool(
                    project, "x" * (antiphon.ATTACHMENT_MAX + 1), "ui")
                opened.assert_not_called()
            said = result["content"][0]["text"]
            self.assertIs(result.get("isError"), True)
            self.assertIn("the channel accepts at most {}".format(
                antiphon.MAX_CHANNEL_BYTES), said)
            self.assertTrue(said.endswith(
                " — " + antiphon.TOOL_GUIDANCE.format(
                    seen="only a tool-name line")), said)
            self.assertFalse(os.path.exists(self._store(project)),
                             "nothing is parked for a message no store takes")

    def test_a_small_send_never_touches_the_store(self):
        """The store directory is created lazily, on the first spill only."""
        with tempfile.TemporaryDirectory() as project:
            antiphon.peers.register(project, "claude", "ui", "/tmp/ui.sock")
            with patch.object(antiphon.socket, "socket", self._LiveSocket()):
                result = antiphon._send_tool(project, "hi", "ui")
            self.assertIsNot(result.get("isError"), True, result)
            self.assertFalse(os.path.exists(self._store(project)))

        with tempfile.TemporaryDirectory() as project:
            self._codex_peer(project, "build", "300:build", self.UUID)
            with patch.object(antiphon.subprocess, "run",
                              return_value=self._Queued()):
                code, out, err = self._reply(project, {"text": "hi", "to": "build"})
            self.assertEqual((code, err), (0, ""))
            self.assertIsNone(json.loads(out)["attachment"])
            self.assertFalse(os.path.exists(self._store(project)))

    def test_the_envelope_fits_both_caps(self):
        """What this forbids is a content preview, or anything else in the
        envelope that grows with the message it stands for.

        The Claude cap is a constant, so that half is fit by construction. The
        queue bound is not — it shrinks byte for byte with the environment — so
        the fit there is measured against the live bound in this same test. The
        envelope is never itself a spill candidate, which is what rules out a
        re-entry when the spill re-composes through the same path.
        """
        alias = "a" * 32
        message_id = self.UUID
        path = os.path.join("/" + "d" * 200, ".antiphon", "messages",
                            self.UUID + ".txt")
        envelope = antiphon.attachment_envelope(
            path, "f" * 64, antiphon.ATTACHMENT_MAX, alias)
        self.assertLess(len(envelope.encode()), 1_024, envelope)
        self.assertFalse(antiphon._oversized_for_claude(
            envelope, alias, message_id))
        composed = "{} {} {}".format(antiphon.CHANNEL_LABEL,
                                     antiphon.queue_label(alias, message_id),
                                     envelope)
        self.assertFalse(antiphon._oversized_for_queue(composed))

    def test_the_store_rejects_foreign_names(self):
        """Only `{uuid4}.txt` is ever counted, swept or unlinked.

        The one foreign entry this feature can create itself is a leftover temp
        file from a write that died mid-flight; a validation rule that admitted
        it would sweep it as though it were an attachment. A symlink carrying a
        perfectly valid name is the other shape: it is refused on the lstat, so
        nothing outside the store is ever unlinked through it.
        """
        with tempfile.TemporaryDirectory() as project:
            store = self._store(project)
            os.makedirs(store, 0o700)
            mine = os.path.join(store, self.UUID + ".txt")
            with open(mine, "w", encoding="utf-8") as f:
                f.write("[Antiphon attachment bytes=2]\n\nhi")
            outside = os.path.join(project, "not-an-attachment.txt")
            with open(outside, "w", encoding="utf-8") as f:
                f.write("somebody else's file")
            foreign = (".tmp9f3a1c.tmp",                   # the writer's own
                       "notes.txt",                        # hand-dropped
                       self.UUID + ".txt.bak",             # a near miss
                       ".." + self.UUID + ".txt")          # traversal-shaped
            for name in foreign:
                with open(os.path.join(store, name), "w", encoding="utf-8") as f:
                    f.write("x")
            link = os.path.join(store, RefusedSendHonestyTest.OTHER + ".txt")
            os.symlink(outside, link)
            expired = time.time() - antiphon.ATTACHMENT_TTL - 60
            for name in os.listdir(store):
                os.utime(os.path.join(store, name), (expired, expired),
                         follow_symlinks=False)

            err = io.StringIO()
            with contextlib.redirect_stderr(err):
                antiphon.sweep_attachments(project)

            left = sorted(os.listdir(store))
            self.assertEqual(left, sorted(foreign + (os.path.basename(link),)),
                             "only the real attachment was swept")
            self.assertTrue(os.path.exists(outside),
                            "the symlink's target is untouched")
            self.assertIn("not attachments", err.getvalue())
            self.assertNotIn("notes.txt", err.getvalue(),
                             "foreign entries are counted, never named — a "
                             "store report is not a directory listing")

class AttachmentReceiptTest(unittest.TestCase):
    """What the ledger adds to a parked attachment: a resend of the same
    words to the same peer names the file that already exists instead of a
    second one; a file the peer's transcript shows being read is collected
    an hour after that receipt; a file nobody read expires on the same TTL
    as before and its sender hears about it on its next page. Measured
    before this: a retry parked a second file under a second uuid, and the
    expiry announcement reached whoever watched that terminal, never the
    reader who never read it."""

    UUID = RefusedSendHonestyTest.UUID
    OTHER = "2e6b14f1-1659-544a-98d4-56d6eca8fa48"

    @staticmethod
    def _codex_peer(project, alias, owner, session=None):
        RefusedSendHonestyTest._codex_peer(project, alias, owner, session)

    @staticmethod
    def _reply(project, payload):
        return RefusedSendHonestyTest._reply(project, payload)

    @classmethod
    def _files(cls, project):
        return AttachmentSpillTest._files(project)

    @staticmethod
    def _queue_recorder(queued):
        return AttachmentSpillTest._queue_recorder(queued)

    @staticmethod
    def _spills_over(size):
        return AttachmentSpillTest._spills_over(size)

    def _entry(self, project, delivery, name, sender="ui", to_alias="build",
               at=None):
        ledger.record_sent(project, delivery, sender=sender, to_kind="codex",
                           to_alias=to_alias, transport="queue", proof="live",
                           sha256="a" * 64, size=5, attachment=name, at=at)

    @staticmethod
    def _sweep(project, now):
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            antiphon.sweep_attachments(project, now)
        return err.getvalue()

    def test_a_resend_of_the_same_words_to_the_same_peer_reuses_the_parked_file(self):
        text = "y" * 4_000
        with tempfile.TemporaryDirectory() as project:
            self._codex_peer(project, "build", "300:build", self.UUID)
            self._codex_peer(project, "review", "301:review", self.OTHER)
            queued = []
            with self._spills_over(500), self._queue_recorder(queued):
                first = json.loads(self._reply(
                    project, {"text": text, "to": "build", "sender_alias": "ui"})[1])
                parked = os.path.join(project, ".antiphon", "messages", first["attachment"])
                aged = time.time() - 3 * 86400
                os.utime(parked, (aged, aged))
                second = json.loads(self._reply(
                    project, {"text": text, "to": "build", "sender_alias": "ui"})[1])
                self.assertEqual(second["attachment"], first["attachment"])
                self.assertEqual(len(self._files(project)), 1, "one file, not one per resend")
                self.assertEqual(len(queued), 2, "two envelopes went")
                self.assertIn(parked, queued[1][-1], "the second envelope names the same file")
                self.assertGreater(os.stat(parked).st_mtime, time.time() - 60,
                                   "the resend restarts the file's clock")
                self.assertEqual([e["attachment"] for e in ledger.entries(project)],
                                 [first["attachment"]] * 2)
                # Not the same words, or not the same peer: a file of its own.
                third = json.loads(self._reply(
                    project, {"text": text, "to": "review", "sender_alias": "ui"})[1])
                fourth = json.loads(self._reply(
                    project, {"text": text + "!", "to": "build", "sender_alias": "ui"})[1])
                # Nor the same words from another session under this one's name.
                fifth = json.loads(self._reply(
                    project, {"text": text, "to": "build", "sender_alias": "other"})[1])
            names = {first["attachment"], third["attachment"], fourth["attachment"],
                     fifth["attachment"]}
            self.assertEqual(len(names), 4)
            self.assertEqual(len(self._files(project)), 4)

    def test_a_failed_resend_never_removes_the_file_the_first_envelope_names(self):
        """Review 2026-09-03, critical: the first envelope is in Codex's queue,
        the same words are sent again and reuse the file, the second send is
        refused — and `drop_attachment` unlinked the file the first envelope
        points at."""
        text = "y" * 4_000
        with tempfile.TemporaryDirectory() as project:
            self._codex_peer(project, "build", "300:build", self.UUID)
            queued = []
            with self._spills_over(500), self._queue_recorder(queued):
                first = json.loads(self._reply(
                    project, {"text": text, "to": "build", "sender_alias": "ui"})[1])
            parked = os.path.join(project, ".antiphon", "messages", first["attachment"])
            with self._spills_over(500), \
                 patch.object(antiphon, "send_to_codex",
                              return_value=(False, "not delivered: nobody")):
                code, _out, err = self._reply(
                    project, {"text": text, "to": "build", "sender_alias": "ui"})
            self.assertEqual(code, 1)
            self.assertTrue(os.path.exists(parked), "the first envelope still names it")
            self.assertNotIn("attachment was removed", err)
            attachment, _refusal = antiphon._spill(project, text, "ui", self.OTHER,
                                                   recipient=("codex", "build"))
            self.assertTrue(attachment.reused)
            fresh, _refusal = antiphon._spill(project, text + "!", "ui", self.OTHER,
                                              recipient=("codex", "build"))
            self.assertFalse(fresh.reused)

    def test_a_file_the_peer_read_is_not_reused_for_a_resend(self):
        text = "y" * 4_000
        with tempfile.TemporaryDirectory() as project:
            self._codex_peer(project, "build", "300:build", self.UUID)
            queued = []
            with self._spills_over(500), self._queue_recorder(queued):
                first = json.loads(self._reply(
                    project, {"text": text, "to": "build", "sender_alias": "ui"})[1])
                ledger.mark_read(project, first["attachment"], time.time() - 7200,
                                 to_kind="codex")
                second = json.loads(self._reply(
                    project, {"text": text, "to": "build", "sender_alias": "ui"})[1])
            self.assertNotEqual(second["attachment"], first["attachment"],
                                "a read file's grace would collect the fresh envelope")
            self.assertEqual(len(self._files(project)), 2)

    def test_a_read_attachment_is_collected_an_hour_after_its_receipt(self):
        with tempfile.TemporaryDirectory() as project:
            fresh, _ = antiphon.write_attachment(project, "words", "ui", self.UUID)
            old, _ = antiphon.write_attachment(project, "other words", "ui", self.OTHER)
            self._entry(project, self.UUID, os.path.basename(fresh))
            self._entry(project, self.OTHER, os.path.basename(old))
            now = time.time()
            ledger.mark_read(project, os.path.basename(fresh), now - 600)
            ledger.mark_read(project, os.path.basename(old), now - 2 * 3600)
            said = self._sweep(project, now)
            self.assertTrue(os.path.exists(fresh), "ten minutes after its read receipt")
            self.assertFalse(os.path.exists(old), "two hours after its read receipt")
            self.assertIn(f"attachment read 120 minutes ago and collected: {old}", said)
            self.assertNotIn("expired", said)
            self.assertIsNone(ledger.read_entry(project, self.OTHER)["expired_unread_at"])
            self.assertEqual(antiphon.ATTACHMENT_READ_GRACE, 3600)

    def test_an_unread_attachment_expires_on_the_ttl_and_its_sender_hears_about_it(self):
        with tempfile.TemporaryDirectory() as project:
            path, _ = antiphon.write_attachment(project, "words", None, self.UUID)
            name = os.path.basename(path)
            aged = time.time() - antiphon.ATTACHMENT_TTL - 86400
            os.utime(path, (aged, aged))
            self._entry(project, self.UUID, name, sender="<unnamed>", at=aged)
            out = io.StringIO()
            with patch.object(antiphon, "project_dir", return_value=project), \
                 patch.object(antiphon, "codex_rollout_files", return_value=[]), \
                 patch.object(antiphon, "claude_transcripts", return_value=[]), \
                 patch.object(antiphon.sys, "stdin", io.StringIO(json.dumps(
                     {"cwd": project, "hook_event_name": "UserPromptSubmit"}))), \
                 contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()) as err:
                self.assertEqual(antiphon.hook("claude"), 0)
            self.assertFalse(os.path.exists(path))
            self.assertIn("expired unread after 8 days and was deleted", err.getvalue())
            entry = ledger.read_entry(project, self.UUID)
            self.assertIsNotNone(entry["expired_unread_at"])
            context = json.loads(out.getvalue())["hookSpecificOutput"]["additionalContext"]
            self.assertRegex(context, r"^Antiphon: the attachment you sent to Codex at "
                                      r"\d\d:\d\d expired unread after 7 days$")

    def test_an_unread_attachment_inside_the_ttl_is_kept(self):
        with tempfile.TemporaryDirectory() as project:
            path, _ = antiphon.write_attachment(project, "words", "ui", self.UUID)
            self._entry(project, self.UUID, os.path.basename(path))
            said = self._sweep(project, time.time() + antiphon.ATTACHMENT_TTL - 60)
            self.assertTrue(os.path.exists(path))
            self.assertEqual(said, "")

    def test_a_file_from_before_the_ledger_expires_as_it_always_did(self):
        with tempfile.TemporaryDirectory() as project:
            path, _ = antiphon.write_attachment(project, "words", "ui", self.UUID)
            said = self._sweep(project, time.time() + antiphon.ATTACHMENT_TTL + 86400)
            self.assertFalse(os.path.exists(path))
            self.assertIn("expired after 8 days and was deleted", said)
            self.assertNotIn("unread", said, "nothing on the ledger says either way")

    def test_status_counts_read_receipts_and_never_deletes(self):
        with tempfile.TemporaryDirectory() as project:
            read, _ = antiphon.write_attachment(project, "words", "ui", self.UUID)
            unread, _ = antiphon.write_attachment(project, "other", "ui", self.OTHER)
            self._entry(project, self.UUID, os.path.basename(read))
            self._entry(project, self.OTHER, os.path.basename(unread))
            ledger.mark_read(project, os.path.basename(read), time.time() - 7200)
            line = antiphon.attachment_report(project)
            self.assertIn("2 parked", line)
            self.assertIn("; 1 with a read receipt, 1 without", line)
            self.assertTrue(os.path.exists(read), "a report never collects")
            self.assertNotIn("read receipt", antiphon.attachment_report(
                tempfile.mkdtemp()), "nothing parked, nothing counted")


class AttachmentLifecycleTest(unittest.TestCase):
    """What happens to a parked attachment after the send that made it.

    Every event here is announced. A file that expires says so, a store that
    is full says so, and `status` says what is waiting — the alternative is a
    directory that grows in silence and a refusal nobody can explain.
    """

    UUID = RefusedSendHonestyTest.UUID
    _DeadSocket = RefusedSendHonestyTest._DeadSocket
    _LiveSocket = RefusedSendHonestyTest._LiveSocket
    _Queued = RefusedSendHonestyTest._Queued
    ASCII_BAND = AttachmentSpillTest.ASCII_BAND

    @staticmethod
    def _codex_peer(project, alias, owner, session=None):
        RefusedSendHonestyTest._codex_peer(project, alias, owner, session)

    @staticmethod
    def _reply(project, payload):
        return RefusedSendHonestyTest._reply(project, payload)

    @staticmethod
    def _store(project):
        return AttachmentSpillTest._store(project)

    @classmethod
    def _files(cls, project):
        return AttachmentSpillTest._files(project)

    @classmethod
    def _park(cls, project, text="parked words", age=0.0, alias=None):
        """One attachment in the store, aged `age` seconds."""
        path, _digest = antiphon.write_attachment(
            project, text, alias, RefusedSendHonestyTest.UUID)
        when = time.time() - age
        os.utime(path, (when, when))
        return path

    @staticmethod
    def _hook(project, side="claude", extra=(), with_cwd=True,
              summary=("", None, 0)):
        """One `UserPromptSubmit` hook, with a summary of the test's choosing.

        The default summary is empty — the ordinary quiet turn, which is the
        path a sweep placed at a successful tail would never reach.
        """
        payload = {"hook_event_name": "UserPromptSubmit"}
        if with_cwd:
            payload["cwd"] = project
        out, err = io.StringIO(), io.StringIO()
        with contextlib.ExitStack() as stack:
            enter = stack.enter_context
            enter(patch.object(antiphon.sys, "stdin",
                               io.StringIO(json.dumps(payload))))
            enter(patch.object(antiphon, "build_summary",
                               return_value=summary))
            enter(contextlib.redirect_stdout(out))
            enter(contextlib.redirect_stderr(err))
            for context in extra:
                enter(context)
            code = antiphon.hook(side)
        return code, out.getvalue(), err.getvalue()

    def test_the_sweep_runs_after_the_cwd_and_before_the_page(self):
        """Its moment, from a call-sequence spy.

        After `cwd` is resolved, because there is no store path before that;
        before the page is built, because a sweep at a successful tail never
        runs on the ordinary quiet turn — `hook` has five exits and that is the
        common one. Outside every lock, because this project measured a slow
        operation under `cursor_lock` at a 5,008 ms hold against a concurrent
        reader's 2,038 ms of patience.
        """
        calls = []

        def sweep(cwd, *_a, **_k):
            calls.append(("sweep", cwd))

        def page(cwd, *_a, **_k):
            calls.append(("page", cwd))
            return "", None, 0

        with tempfile.TemporaryDirectory() as project:
            code, _out, _err = self._hook(project, extra=[
                patch.object(antiphon, "sweep_attachments", side_effect=sweep),
                patch.object(antiphon, "build_summary", side_effect=page)])
            self.assertEqual(code, 0)
            self.assertEqual([what for what, _ in calls], ["sweep", "page"])
            self.assertEqual(calls[0][1], os.path.abspath(project),
                             "the sweep is handed the resolved cwd")

    def test_an_expired_attachment_is_swept_by_any_hook(self):
        """Including the quiet turn, and out loud. An unexpired one stays."""
        with tempfile.TemporaryDirectory() as project:
            expired = self._park(project, "old words",
                                 age=antiphon.ATTACHMENT_TTL + 3600)
            fresh = self._park(project, "new words", age=3600)
            code, out, err = self._hook(project)
            self.assertEqual((code, out), (0, ""))
            self.assertFalse(os.path.exists(expired))
            self.assertTrue(os.path.exists(fresh))
            self.assertIn(expired, err)
            self.assertIn("expired", err)
            self.assertNotIn(fresh, err)

    def test_a_hook_on_the_fallback_root_never_sweeps(self):
        """`cwd` comes from the payload or from `project_dir()`, and this code
        deliberately does not trust the second — a hook process's own working
        directory is not a claim about which project it serves. No payload
        `cwd`, no sweep: deleting a person's files off a guess is not a
        lifecycle."""
        with tempfile.TemporaryDirectory() as project:
            expired = self._park(project, "old words",
                                 age=antiphon.ATTACHMENT_TTL + 3600)
            swept = []
            code, _out, err = self._hook(
                project, with_cwd=False,
                extra=[patch.object(antiphon, "project_dir",
                                    return_value=project),
                       patch.object(antiphon, "sweep_attachments",
                                    side_effect=lambda *a, **k: swept.append(a))])
            self.assertEqual(code, 0)
            self.assertEqual(swept, [])
            self.assertTrue(os.path.exists(expired))
            self.assertEqual(err, "")

    def test_the_sweep_can_never_change_the_hook_exit_code(self):
        """A non-zero exit suppresses the page this hook exists to deliver, so
        nothing the sweep can do may reach it."""
        with tempfile.TemporaryDirectory() as project:
            code, _out, err = self._hook(project, extra=[
                patch.object(antiphon, "sweep_attachments",
                             side_effect=OSError(errno.EIO, "I/O error"))])
            self.assertEqual(code, 0)
            self.assertIn("attachment", err.lower())

    def test_a_full_store_refuses_without_deleting_anything(self):
        """At quota the send is refused with the store's honest state, and
        nothing is evicted: an unexpired attachment is somebody's undelivered
        words, and making room by deleting them would be the silent loss this
        whole feature exists to remove.

        The refusal is UNCLASSED. `_ClassifiedRefusal`'s own invariant is that
        a class means "the sender needs telling where its words still travel";
        this refusal names its own fix instead, so it joins the addressing
        family and stays byte-identical by construction. The object is asserted
        because the two renderings are not distinguishable — measured, a
        classed and an unclassed refusal print identically, since the class is
        a `str` subclass.
        """
        with tempfile.TemporaryDirectory() as project, \
             patch.object(antiphon, "ATTACHMENT_QUOTA", 4_096):
            antiphon.peers.register(project, "claude", "ui", "/tmp/ui.sock")
            held = self._park(project, "z" * 4_000)
            before = self._files(project)

            attachment, detail = antiphon._spill(project, self.ASCII_BAND,
                                                 None, self.UUID)
            self.assertIsNone(attachment)
            self.assertIsNone(getattr(detail, "refusal_class", None),
                              "a class would attach the passive-page guidance "
                              "to a refusal that names its own fix")

            with patch.object(antiphon.socket, "socket") as opened:
                result = antiphon._send_tool(project, self.ASCII_BAND, "ui")
                opened.assert_not_called()
            said = result["content"][0]["text"]
            self.assertIs(result.get("isError"), True)
            self.assertIn("attachment store", said)
            self.assertNotIn(antiphon.TOOL_GUIDANCE.format(
                seen="only a tool-name line"), said)
            self.assertEqual(self._files(project), before,
                             "nothing was evicted and nothing was added")
            self.assertTrue(os.path.exists(held))

        # The `reply()` side mirrors it, with the same unclassed text.
        with tempfile.TemporaryDirectory() as project, \
             patch.object(antiphon, "ATTACHMENT_QUOTA", 4_096):
            self._codex_peer(project, "build", "300:build", self.UUID)
            held = self._park(project, "z" * 4_000)
            with AttachmentSpillTest._spills_over(500), \
                 patch.object(antiphon.subprocess, "run",
                              return_value=self._Queued()):
                code, _out, err = self._reply(project, {"text": "y" * 4_000,
                                                        "to": "build"})
            self.assertEqual(code, 1)
            self.assertIn("attachment store", err)
            self.assertNotIn(antiphon.TOOL_GUIDANCE.format(
                seen="only a tool-name line"), err)
            self.assertTrue(os.path.exists(held))

    def test_status_reports_the_store_and_never_touches_it(self):
        """Count, content bytes and the oldest age in whole days — no names.

        `status` is a reader. It does not sweep: a person asking what is
        pending must not be the thing that deletes it, and a status run that
        changed the store would make two consecutive runs disagree, which is
        the pin `test_status_lists_peers_in_a_stable_order` already holds.
        """
        with tempfile.TemporaryDirectory() as project:
            fresh = self._park(project, "y" * 1_500, age=3 * 86_400 + 60)
            expired = self._park(project, "y" * 700,
                                 age=antiphon.ATTACHMENT_TTL + 3600)
            before = self._files(project)

            def run():
                out = io.StringIO()
                with patch.object(antiphon, "project_dir",
                                  return_value=project), \
                     contextlib.redirect_stdout(out), \
                     contextlib.redirect_stderr(io.StringIO()):
                    antiphon.status()
                return out.getvalue()

            first, second = run(), run()
            self.assertEqual(first, second, "two runs a second apart agree")
            line = next(row for row in first.splitlines()
                        if row.startswith("Attachments:"))
            self.assertIn("1 parked", line, "the expired one is not pending")
            self.assertIn("1,500 bytes", line)
            self.assertIn("3 days old", line)
            self.assertNotIn(os.path.basename(fresh), first)
            self.assertNotIn(os.path.basename(expired), first)
            self.assertNotIn(self._store(project), first)
            self.assertEqual(self._files(project), before,
                             "status swept nothing")

    def test_status_says_so_when_nothing_is_parked(self):
        """A line that only appears when something is wrong teaches nobody what
        it means when it does."""
        with tempfile.TemporaryDirectory() as project:
            out = io.StringIO()
            with patch.object(antiphon, "project_dir", return_value=project), \
                 contextlib.redirect_stdout(out), \
                 contextlib.redirect_stderr(io.StringIO()):
                antiphon.status()
            self.assertIn("Attachments:        none parked", out.getvalue())

class AttachmentStoreSafetyTest(unittest.TestCase):
    """The store is a directory this code owns outright, or it is not used.

    Two measured holes closed here. A quota read and the write it authorizes
    were two separate operations, so two peers sending at once both passed a
    check neither invalidated. And the store root was taken on trust, so a
    `.antiphon/messages` symlinked at somewhere else put the words there and
    counted them as if they were here.
    """

    UUID = RefusedSendHonestyTest.UUID

    @staticmethod
    def _store(project):
        return AttachmentSpillTest._store(project)

    # One child: park 700 bytes against a 1,000-byte quota, released from a
    # barrier the parent opens once both are waiting on it. Two processes
    # rather than two threads because the lock is the thing under test and a
    # test that could pass on the GIL would prove nothing about two terminals.
    CHILD = (
        "import os, sys, time\n"
        "sys.path.insert(0, sys.argv[1])\n"
        "import antiphon\n"
        "antiphon.ATTACHMENT_QUOTA = 1000\n"
        "project, tag, barrier = sys.argv[2:5]\n"
        "open(os.path.join(barrier, 'ready-' + tag), 'w').close()\n"
        "go = os.path.join(barrier, 'go')\n"
        "deadline = time.time() + 20\n"
        "while not os.path.exists(go) and time.time() < deadline:\n"
        "    pass\n"
        "attachment, _refusal = antiphon._spill(project, 'z' * 700, None,\n"
        "                                       'id-' + tag)\n"
        "print('OK' if attachment is not None else 'REFUSED')\n")

    def _race(self, project):
        """Two concurrent spills into `project`; what each of them said."""
        script = os.path.join(project, "child.py")
        with open(script, "w", encoding="utf-8") as handle:
            handle.write(self.CHILD)
        barrier = os.path.join(project, "barrier")
        os.makedirs(barrier)
        lib = os.path.join(os.path.dirname(os.path.abspath(antiphon.__file__)))
        kids = [subprocess.Popen(
            [sys.executable, script, lib, project, tag, barrier],
            stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True)
            for tag in ("a", "b")]
        deadline = time.time() + 20
        while (len([n for n in os.listdir(barrier)
                    if n.startswith("ready-")]) < 2
               and time.time() < deadline):
            time.sleep(0.001)
        with open(os.path.join(barrier, "go"), "w", encoding="utf-8"):
            pass
        return sorted(kid.communicate()[0].strip() for kid in kids)

    def test_two_peers_at_the_quota_cannot_both_pass_it(self):
        """The check and the write are one transaction.

        Measured before the lock: five rounds out of five, both children
        succeeded and a 1,000-byte store held 1,400. Repeated here so the gate
        cannot pass by luck — one lucky serialization would otherwise read as
        a fix.
        """
        for attempt in range(3):
            with self.subTest(round=attempt), \
                 tempfile.TemporaryDirectory() as project:
                said = self._race(project)
                _count, held, _oldest, _foreign = antiphon.attachment_usage(
                    project)
                self.assertEqual(said, ["OK", "REFUSED"],
                                 "exactly one of the two may park")
                self.assertLessEqual(held, 1000,
                                     "and the store never goes over quota")

    def test_the_store_lock_is_not_held_across_the_send(self):
        """The lock covers the quota decision and the write, and nothing else.

        A lock held across a transport is the mistake this project already
        measured elsewhere: a 5,008 ms hold against a concurrent reader's own
        2,038 ms of patience, after which that reader gave up having delivered
        no context at all. Proved from inside the send itself rather than by
        reading the code.
        """
        with tempfile.TemporaryDirectory() as project:
            antiphon.peers.register(project, "claude", "ui", "/tmp/ui.sock")
            free = []

            def send(cwd, _text, *_args, **_kw):
                # A second descriptor on the same file, which `flock` treats
                # exactly as another process would.
                with antiphon.attachment_lock(cwd) as locked:
                    free.append(locked)
                return True, ""

            with patch.object(antiphon, "send_to_claude", side_effect=send):
                antiphon._send_tool(project, AttachmentSpillTest.ASCII_BAND,
                                    "ui")
            self.assertEqual(free, [True],
                             "the store lock was already released")

    def test_a_symlinked_store_is_refused_rather_than_followed(self):
        """The words would have landed outside the project, and been counted as
        though they were inside it."""
        with tempfile.TemporaryDirectory() as project, \
             tempfile.TemporaryDirectory() as elsewhere:
            os.makedirs(os.path.join(project, ".antiphon"))
            os.symlink(elsewhere, self._store(project))
            err = io.StringIO()
            with contextlib.redirect_stderr(err):
                with self.assertRaises(OSError):
                    antiphon.write_attachment(project, "secret words", None,
                                              self.UUID)
                usage = antiphon.attachment_usage(project)
                antiphon.sweep_attachments(project)
            self.assertEqual(os.listdir(elsewhere), [],
                             "nothing was written through the link")
            self.assertEqual(usage[:2], (0, 0),
                             "and nothing outside the project was counted")
            self.assertIn("attachment store", err.getvalue())

    def test_a_loose_store_mode_is_tightened_before_anything_is_written(self):
        """`makedirs(exist_ok=True)` leaves a directory's mode exactly as it
        found it, so a store somebody once created 0755 stayed 0755 — holding
        one side's words for the other, readable by anyone on the machine."""
        with tempfile.TemporaryDirectory() as project:
            store = self._store(project)
            os.makedirs(store)
            os.chmod(store, 0o755)
            err = io.StringIO()
            with contextlib.redirect_stderr(err):
                path, _digest = antiphon.write_attachment(project, "words",
                                                          None, self.UUID)
            self.assertEqual(os.stat(store).st_mode & 0o777, 0o700)
            self.assertEqual(os.stat(path).st_mode & 0o777, 0o600)
            self.assertIn("0700", err.getvalue())

    def test_a_path_outside_the_store_cannot_be_dropped_through_it(self):
        """`drop_attachment` runs on the failure path of a send, on a path the
        caller supplies. It removes an attachment of this project's or it
        removes nothing — a valid-looking uuid name is not authority."""
        with tempfile.TemporaryDirectory() as project, \
             tempfile.TemporaryDirectory() as elsewhere:
            victim = os.path.join(elsewhere, self.UUID + ".txt")
            with open(victim, "w", encoding="utf-8") as handle:
                handle.write("somebody else's file")
            mine, _digest = antiphon.write_attachment(project, "words", None,
                                                      self.UUID)
            err = io.StringIO()
            with contextlib.redirect_stderr(err):
                antiphon.drop_attachment(project, victim)
            self.assertTrue(os.path.exists(victim), "refused, and said so")
            self.assertIn("refus", err.getvalue().lower())

            with contextlib.redirect_stderr(io.StringIO()):
                antiphon.drop_attachment(project, mine)
            self.assertFalse(os.path.exists(mine),
                             "while this project's own attachment goes")

if __name__ == "__main__":
    unittest.main()


class AutomaticReadyVerdictTest(unittest.TestCase):
    """One predicate, consumed by everything that decides.

    A boolean could not drive self-retirement: the same false covers a listener
    whose proof has not been written yet and a listener whose proof now names
    someone else. The first is bootstrap or a transient read error and must fail
    closed without destroying anything; only the second is the stale identity
    this repair retires.
    """

    SESSION = "8261c119-2c20-4bf4-87ab-f152ac87dbda"
    OTHER = "0199a1b2-2222-7000-8000-00000000000b"
    OWNER = "4242:v1:Mon Sep  1 00:00:00 2026"

    def _automatic_peer(self, project, session_id=None):
        session_id = session_id or self.SESSION
        alias, digest = antiphon.peers.auto_identity(session_id)
        socket = os.path.join(project, alias + ".sock")
        antiphon.peers.register(project, "claude", alias, socket,
                                pid=os.getpid(), owner_key=self.OWNER,
                                identity_digest=digest)
        antiphon.peers.write_session(project, "claude", alias, session_id,
                                     f"/t/{alias}.jsonl", self.OWNER, digest,
                                     True)
        for peer in antiphon.peers.read_peers(project, "claude"):
            if peer.get("name") == alias:
                return peer
        raise AssertionError("the fixture did not produce a readable peer")

    def _verdict(self, project, peer):
        state, proof = antiphon.peers.read_identity_proof(project, self.OWNER)
        return antiphon.automatic_verdict(project, "claude", peer,
                                          (state, proof))

    def test_automatic_ready_requires_endpoint_session_and_proof(self):
        with tempfile.TemporaryDirectory() as project:
            peer = self._automatic_peer(project)
            self.assertEqual(self._verdict(project, peer), "UNREADY",
                             "no proof has been written yet")
            antiphon.peers.write_identity_proof(
                project, self.OWNER, self.SESSION,
                antiphon.peers.auto_identity(self.SESSION)[1])
            self.assertEqual(self._verdict(project, peer), "READY")

    def test_automatic_ready_separates_unready_unknown_from_proved_stale(self):
        """Three answers that a bool would have made one."""
        with tempfile.TemporaryDirectory() as project:
            peer = self._automatic_peer(project)
            self.assertEqual(self._verdict(project, peer), "UNREADY")

            antiphon.peers.write_identity_proof(
                project, self.OWNER, self.OTHER,
                antiphon.peers.auto_identity(self.OTHER)[1])
            self.assertEqual(self._verdict(project, peer), "PROVED_STALE",
                             "a valid proof naming another session")

            self.assertEqual(
                antiphon.automatic_verdict(project, "claude", peer,
                                           ("unreadable", None)),
                "UNKNOWN", "a transient read error must not retire anything")
            self.assertEqual(
                antiphon.automatic_verdict(project, "claude", peer,
                                           ("invalid", None)),
                "STRUCTURAL_INVALID")

    def test_automatic_ready_leaves_explicit_and_codex_peers_alone(self):
        """Scope is structural: this contract governs automatic Claude only."""
        with tempfile.TemporaryDirectory() as project:
            antiphon.peers.register(project, "claude", "build",
                                    os.path.join(project, "build.sock"),
                                    pid=os.getpid(), owner_key=self.OWNER)
            explicit = [p for p in antiphon.peers.read_peers(project, "claude")
                        if p.get("name") == "build"][0]
            self.assertIsNone(
                antiphon.automatic_verdict(project, "claude", explicit,
                                           ("absent", None)),
                "an explicit peer is not governed by the proof")
            automatic = self._automatic_peer(project)
            self.assertIsNone(
                antiphon.automatic_verdict(project, "codex", automatic,
                                           ("absent", None)),
                "no Codex path is governed by the proof")

    def test_automatic_ready_stops_claimed_alias_signing_after_rotation(self):
        """Behavioural through the production Stop-signing identity."""
        with tempfile.TemporaryDirectory() as project:
            self._automatic_peer(project)
            alias = antiphon.peers.auto_identity(self.SESSION)[0]
            with patch.object(antiphon.peers, "owner_key",
                              return_value=self.OWNER):
                antiphon.peers.write_identity_proof(
                    project, self.OWNER, self.SESSION,
                    antiphon.peers.auto_identity(self.SESSION)[1])
                self.assertEqual(
                    antiphon.claimed_alias(project, "claude", self.SESSION),
                    alias, "a valid proof signs the automatic alias")

                antiphon.peers.write_identity_proof(
                    project, self.OWNER, self.OTHER,
                    antiphon.peers.auto_identity(self.OTHER)[1])
                self.assertIsNone(
                    antiphon.claimed_alias(project, "claude", self.SESSION),
                    "once the proof names another session, nothing automatic "
                    "may be signed")

    def test_automatic_ready_is_the_only_copy_of_the_rule(self):
        """Resolver, status and doctor must all reach the same verdict.

        Patching the predicate is enough to change every decision; if any
        surface kept its own copy, one of these would disagree.
        """
        with tempfile.TemporaryDirectory() as project:
            self._automatic_peer(project)
            alias = antiphon.peers.auto_identity(self.SESSION)[0]
            antiphon.peers.write_identity_proof(
                project, self.OWNER, self.SESSION,
                antiphon.peers.auto_identity(self.SESSION)[1])
            with patch.object(antiphon, "automatic_verdict",
                              return_value="PROVED_STALE"):
                resolved = antiphon._resolve_target(project, "claude", alias)
                self.assertIsNone(resolved.address,
                                  "the resolver consults the predicate")
                # This docstring named three surfaces and measured one, and
                # doctor was the one that had kept its own copy: it read
                # record liveness alone and printed `✓ live and addressed`
                # for the very alias the resolver had just refused. An
                # operator runs doctor precisely because delivery is failing.
                out = io.StringIO()
                with patch.object(antiphon, "project_dir",
                                  return_value=project), \
                     contextlib.redirect_stdout(out):
                    antiphon.status()
                self.assertNotIn(alias, out.getvalue(),
                                 "status consults the predicate")
                out = io.StringIO()
                report = antiphon._Report()
                with contextlib.redirect_stdout(out):
                    antiphon._doctor_peers(report, project)
                lines = [line for line in out.getvalue().splitlines()
                         if alias in line]
                self.assertTrue(lines, out.getvalue())
                for line in lines:
                    self.assertNotIn("live and addressed", line,
                                     "doctor consults the predicate too")
                    self.assertIn(antiphon.RECONNECT_REMEDY, line,
                                  "and offers the remedy the others do")


class HookIdentityCommitTest(unittest.TestCase):
    """The Claude hook rotates the proof before it decides anything else."""

    OWNER = "4242:v1:Mon Sep  1 00:00:00 2026"
    A = "8261c119-2c20-4bf4-87ab-f152ac87dbda"
    B = "0199a1b2-2222-7000-8000-00000000000b"

    def _half(self, project, session_id):
        alias, digest = antiphon.peers.auto_identity(session_id)
        antiphon.peers.register(project, "claude", alias,
                                os.path.join(project, alias + ".sock"),
                                pid=os.getpid(), owner_key=self.OWNER,
                                identity_digest=digest)
        antiphon.peers.write_session(project, "claude", alias, session_id,
                                     f"/t/{alias}.jsonl", self.OWNER, digest,
                                     True)
        return alias

    def test_hook_identity_commit_precedes_any_join_decision(self):
        order = []
        with tempfile.TemporaryDirectory() as project, \
             patch.object(antiphon.peers, "owner_key",
                          return_value=self.OWNER):
            real_rotate = antiphon.peers.rotate_identity_proof
            real_write = antiphon.peers.write_session

            def rotate(*a, **k):
                order.append("rotate")
                return real_rotate(*a, **k)

            def write(*a, **k):
                order.append("join")
                return real_write(*a, **k)

            with patch.object(antiphon.peers, "rotate_identity_proof", rotate), \
                 patch.object(antiphon.peers, "write_session", write):
                antiphon.record_claude_session(project, self.A, "/t/a.jsonl")
        self.assertEqual(order[:2], ["rotate", "join"],
                         "the proof is current before anything is joined")

    def test_hook_identity_is_never_written_for_explicit_or_invalid_names(self):
        for name in ("build", "Not A Name!"):
            with self.subTest(configured=name), \
                 tempfile.TemporaryDirectory() as project, \
                 patch.dict(os.environ, {"ANTIPHON_NAME": name}), \
                 patch.object(antiphon.peers, "owner_key",
                              return_value=self.OWNER):
                antiphon.record_claude_session(project, self.A, "/t/a.jsonl")
                self.assertEqual(
                    antiphon.peers.read_identity_proof(project, self.OWNER),
                    ("absent", None),
                    "the proof is a fact about automatic identity only")

    def test_hook_identity_sends_at_most_one_bounded_wakeup(self):
        sent = []
        with tempfile.TemporaryDirectory() as project, \
             patch.object(antiphon.peers, "owner_key",
                          return_value=self.OWNER):
            self._half(project, self.A)
            antiphon.peers.rotate_identity_proof(
                project, self.OWNER, self.A,
                antiphon.peers.auto_identity(self.A)[1])
            self._half(project, self.B)
            with patch.object(antiphon, "_retire_control",
                              side_effect=lambda *a, **k: sent.append(a)):
                antiphon.record_claude_session(project, self.B, "/t/b.jsonl")
        self.assertEqual(len(sent), 1,
                         "one wakeup, to the previous current alias only")

    def test_hook_identity_survives_a_failed_wakeup(self):
        with tempfile.TemporaryDirectory() as project, \
             patch.object(antiphon.peers, "owner_key",
                          return_value=self.OWNER):
            self._half(project, self.A)
            antiphon.peers.rotate_identity_proof(
                project, self.OWNER, self.A,
                antiphon.peers.auto_identity(self.A)[1])
            self._half(project, self.B)

            def explode(*_a, **_k):
                raise OSError(5, "Input/output error")

            with patch.object(antiphon, "_retire_control", explode):
                self.assertTrue(
                    antiphon.record_claude_session(project, self.B,
                                                   "/t/b.jsonl"),
                    "the Stop hook is the hottest path; a control that cannot "
                    "be delivered may not fail it")
            state, proof = antiphon.peers.read_identity_proof(project,
                                                             self.OWNER)
            self.assertEqual((state, proof["session_id"]), ("valid", self.B))


class AutomaticRegistrationBridgeTest(unittest.TestCase):
    """The bridge is where the mode becomes mandatory for automatic Claude.

    The direct API stays usable without one so explicit peers, Codex and the
    suite's own fixtures keep working; the bridge is the caller that always
    knows which kind of claim it is making, so it must always say.
    """

    OWNER = "4242:v1:Mon Sep  1 00:00:00 2026"
    A = "8261c119-2c20-4bf4-87ab-f152ac87dbda"

    def _call(self, project, payload):
        out, err = io.StringIO(), io.StringIO()
        with patch.object(antiphon, "project_dir", return_value=project), \
             patch.object(antiphon.peers, "owner_key",
                          return_value=self.OWNER), \
             patch.object(sys, "stdin", io.StringIO(json.dumps(payload))), \
             contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            code = antiphon.register_peer()
        return code, out.getvalue() + err.getvalue()

    def test_automatic_registration_bridge_requires_a_mode(self):
        alias, digest = antiphon.peers.auto_identity(self.A)
        with tempfile.TemporaryDirectory() as project:
            code, printed = self._call(project, {
                "kind": "claude", "name": alias,
                "address": os.path.join(project, "a.sock"),
                "pid": os.getpid(), "identity_digest": digest,
                "fingerprint_field": "process_birth",
            })
            self.assertEqual(code, 1, printed)
            self.assertEqual(antiphon.peers.read_peers(project, "claude"), [],
                             "a modeless automatic claim registers nothing")

    def test_automatic_registration_bridge_passes_a_valid_mode_through(self):
        alias, digest = antiphon.peers.auto_identity(self.A)
        with tempfile.TemporaryDirectory() as project:
            code, printed = self._call(project, {
                "kind": "claude", "name": alias,
                "address": os.path.join(project, "a.sock"),
                "pid": os.getpid(), "identity_digest": digest,
                "mode": "initial", "fingerprint_field": "process_birth",
            })
            self.assertEqual(code, 0, printed)
            self.assertEqual(
                [p.get("name") for p in
                 antiphon.peers.read_peers(project, "claude")], [alias])

    def test_automatic_registration_bridge_refuses_an_undeclared_claim(self):
        """A listener that does not say which fingerprint field its verdict
        reads is an older Node over a newer Python: registering it would
        publish an endpoint its own in-memory verdict cannot govern, and a
        sender would be told it recovered and then refused. Both modes."""
        alias, digest = antiphon.peers.auto_identity(self.A)
        for mode in ("initial", "reassert"):
            with self.subTest(mode=mode), \
                    tempfile.TemporaryDirectory() as project:
                code, printed = self._call(project, {
                    "kind": "claude", "name": alias,
                    "address": os.path.join(project, "a.sock"),
                    "pid": os.getpid(), "identity_digest": digest,
                    "mode": mode,
                })
                self.assertEqual(code, 1, printed)
                self.assertEqual(antiphon.peers.read_peers(project, "claude"), [],
                                 "an undeclared automatic claim registers nothing")
                self.assertRegex(printed, r"predates the registry's fingerprint field")
                self.assertIn("reconnect the Claude session", printed)

    def test_automatic_registration_bridge_leaves_explicit_claims_alone(self):
        with tempfile.TemporaryDirectory() as project:
            code, printed = self._call(project, {
                "kind": "claude", "name": "build",
                "address": os.path.join(project, "b.sock"),
                "pid": os.getpid(),
            })
            self.assertEqual(code, 0, printed)


class StaleInboundClassTest(unittest.TestCase):
    """A refusal the listener classified must not be recast as transport.

    "The socket failed" and "that alias is not this session any more" call for
    different actions, and only the second tells a sender to reconnect. This
    drives the real `send_to_claude` against a real listening socket rather
    than a stub, so the red cannot come from a fallback branch.
    """

    def _listener(self, project, reply, close_first=False):
        """A listener that answers, optionally closing before the sender is done.

        `close_first` is the real listener's fast path, not an exotic one: it
        refuses a stale identity, flushes, and withdraws. On macOS the sender's
        `shutdown(SHUT_WR)` then raises `ENOTCONN`, and this fixture only hit
        that race sometimes — measured at 6 failures in 12 runs — so the suite
        was not reliably green and the flake hid a real substitution: the
        listener's classified answer, already in the receive buffer, thrown
        away and relabelled `transport`.
        """
        path = os.path.join(project, "peer.sock")
        server = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        server.bind(path)
        server.listen(1)
        answered = threading.Event()

        def serve():
            conn, _ = server.accept()
            with conn:
                conn.recv(65536)
                if not close_first:
                    # Read to EOF as the real listener does, so the sender's
                    # half-close lands before the answer.
                    while conn.recv(65536):
                        pass
                conn.sendall(json.dumps(reply).encode("utf-8"))
            answered.set()
        thread = threading.Thread(target=serve, daemon=True)
        thread.start()
        return path, server, thread, answered

    def test_stale_inbound_no_peer_class_is_not_recast_as_transport(self):
        with tempfile.TemporaryDirectory() as project:
            path, server, thread, _answered = self._listener(project, {
                "ok": False, "error": "identity moved",
                "refusal_class": "no-peer"})
            try:
                target = antiphon.ResolvedTarget(path, "", "registered")
                with patch.object(antiphon, "_resolve_target",
                                  return_value=target):
                    ok, detail = antiphon.send_to_claude(project, "hello")
            finally:
                thread.join(2)
                server.close()
        self.assertFalse(ok)
        self.assertIn("identity moved", str(detail),
                      "the listener's own words, not a fallback refusal that "
                      "happens to carry the same class")
        self.assertEqual(getattr(detail, "refusal_class", None), "no-peer",
                         "a class the listener supplied survives the return; "
                         "recasting it as transport would tell the sender to "
                         "blame the socket instead of reconnecting")

    def test_stale_inbound_survives_a_listener_that_closes_first(self):
        """The same guarantee against the listener's own fast path.

        A proved-stale listener answers and withdraws, so its socket can be
        gone by the time the sender half-closes. On macOS that `shutdown`
        raises `ENOTCONN` — and it sat inside the arm that relabels everything
        `transport`, so the classified answer already sitting in the receive
        buffer was discarded and the sender was told to blame the socket.
        """
        with tempfile.TemporaryDirectory() as project:
            path, server, thread, answered = self._listener(
                project, {"ok": False, "error": "identity moved",
                          "refusal_class": "no-peer"}, close_first=True)
            try:
                target = antiphon.ResolvedTarget(path, "", "registered")
                # The failure is injected, not waited for. Hoping the listener
                # closes first made this bite 4 runs in 12 — and the waits that
                # were supposed to force the ordering were `x or True`, which
                # cannot fail and cannot order anything either.
                with patch.object(antiphon, "_resolve_target",
                                  return_value=target), \
                     patch.object(antiphon.socket, "socket",
                                  _RefusesShutdown):
                    ok, detail = antiphon.send_to_claude(project, "hello")
                self.assertTrue(answered.wait(2),
                                "the listener did answer; its words are what "
                                "must survive")
            finally:
                thread.join(2)
                server.close()
        self.assertFalse(ok)
        self.assertIn("identity moved", str(detail),
                      "the listener's own words survive its early close")
        self.assertEqual(getattr(detail, "refusal_class", None), "no-peer")


class _RefusesShutdown(socket.socket):
    """A socket whose half-close fails the way this platform's does.

    `shutdown(SHUT_WR)` raises ENOTCONN once the peer has gone, and that call
    sat inside the arm that relabels every refusal `transport`. Injecting it is
    the only way to test the consequence without racing the scheduler.
    """

    def shutdown(self, how):
        raise OSError(errno.ENOTCONN, "Socket is not connected")


class ReadinessParityTest(unittest.TestCase):
    """Python and Node must reach the same verdict, with the same reason.

    Agreement on a boolean would not be agreement at all: two readers returning
    "not ready" for different reasons still disagree about whether to retire.
    """

    OWNER = "4242:v1:Mon Sep  1 00:00:00 2026"
    A = "8261c119-2c20-4bf4-87ab-f152ac87dbda"
    B = "0199a1b2-2222-7000-8000-00000000000b"
    C = "0199a1b2-3333-7000-8000-00000000000c"
    ROOT = os.path.dirname(os.path.dirname(os.path.abspath(antiphon.__file__)))

    def _peer(self, project):
        alias, digest = antiphon.peers.auto_identity(self.A)
        antiphon.peers.register(project, "claude", alias,
                                os.path.join(project, alias + ".sock"),
                                pid=os.getpid(), owner_key=self.OWNER,
                                identity_digest=digest)
        antiphon.peers.write_session(project, "claude", alias, self.A,
                                     f"/t/{alias}.jsonl", self.OWNER,
                                     digest, True)
        return alias, digest

    def _proof(self, project, session_id, **over):
        antiphon.peers.write_identity_proof(
            project, self.OWNER, session_id,
            antiphon.peers.auto_identity(session_id)[1])
        if not over:
            return
        path = antiphon.peers.identity_proof_path(project, self.OWNER)
        with open(path, encoding="utf-8") as stream:
            record = json.load(stream)
        record.update(over)
        with open(path, "w", encoding="utf-8") as stream:
            json.dump(record, stream)

    @staticmethod
    def _write(path, body):
        with open(path, "w", encoding="utf-8") as stream:
            stream.write(body)

    def _raw(self, project, body):
        path = antiphon.peers.identity_proof_path(project, self.OWNER)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as stream:
            stream.write(body)

    OTHER_OWNER = "4243:v1:Mon Sep  1 00:00:00 2026"

    def _body(self, project, session_id, version_literal="1"):
        """One proof as text, so a spelling JSON cannot preserve can be tested.

        JSON has one number type: `1.0` parses to the same `1` an integer does,
        so no check on the parsed value can tell them apart. Python's
        `isinstance(version, int)` refuses the float and Node could not see it
        at all — the divergence is only reachable through the source text.
        """
        _alias, digest = antiphon.peers.auto_identity(session_id)
        return ('{"version": ' + version_literal + ', "kind": "claude", '
                f'"owner_key": "{self.OWNER}", '
                f'"owner_digest": "{antiphon.peers._owner_digest(self.OWNER)}", '
                f'"session_id": "{session_id}", '
                f'"identity_digest": "{digest}"}}')

    def _patch(self, path, drop=None, **over):
        with open(path, encoding="utf-8") as stream:
            record = json.load(stream)
        if drop:
            record.pop(drop, None)
        record.update(over)
        with open(path, "w", encoding="utf-8") as stream:
            json.dump(record, stream)

    def _withdrawn(self, project, alias, owner=None, digest=None,
                   version_literal="1", extra="", kind="claude",
                   session_id=None):
        """The state a rotation actually leaves: no half, one tombstone."""
        os.unlink(os.path.join(
            antiphon.peers.peer_dir(project, "claude", alias), "session.json"))
        _name, own_digest = antiphon.peers.auto_identity(self.A)
        self._write(
            antiphon.peers.retired_half_path(project, "claude", alias),
            '{"version": ' + version_literal + f', "kind": "{kind}", '
            f'"owner": "{owner or self.OWNER}", '
            f'"identity_digest": "{digest or own_digest}", '
            f'"session_id": "{session_id or self.A}"{extra}}}')

    @staticmethod
    def _own_birth():
        """The birth the registry records for this test process, as a listener
        would remember it from its own claim."""
        return antiphon.peers._process_birth(os.getpid()) or ""

    @staticmethod
    def _bom(path, _ignored=None):
        with open(path, "rb") as stream:
            raw = stream.read()
        with open(path, "wb") as stream:
            stream.write(b"\xef\xbb\xbf" + raw)

    @staticmethod
    def _reaped_pid():
        """A pid that named a process and does not now."""
        child = subprocess.Popen([sys.executable, "-c", "pass"])
        child.wait()
        return child.pid

    @staticmethod
    def _read(path):
        with open(path, encoding="utf-8") as stream:
            return stream.read()

    @staticmethod
    def _corrupt_bytes(path):
        """One byte no UTF-8 decoder may accept, inside a string value."""
        with open(path, "rb") as stream:
            raw = stream.read()
        with open(path, "wb") as stream:
            stream.write(raw.replace(b'"claude"', b'"cl\xffude"', 1))

    @staticmethod
    def _rewrite(path, transform):
        with open(path, encoding="utf-8") as stream:
            text = stream.read()
        with open(path, "w", encoding="utf-8") as stream:
            stream.write(transform(text))

    @staticmethod
    def _corrupt(path):
        """One byte no UTF-8 decoder may accept, inside a string value."""
        with open(path, "rb") as stream:
            raw = stream.read()
        assert b'"address"' in raw, raw[:80]
        with open(path, "wb") as stream:
            stream.write(raw.replace(b'"address": "', b'"address": "\xff', 1))

    @staticmethod
    def _pad(path):
        """Push a record past the ceiling without changing what it says.

        Whitespace between tokens, not an extra key: JSON ignores it, so both
        parsers read exactly the same record and the only thing under test is
        the size. Padding with a field measured the exact-key check instead —
        the fixture agreed with itself for the wrong reason.
        """
        with open(path, encoding="utf-8") as stream:
            raw = stream.read()
        with open(path, "w", encoding="utf-8") as stream:
            stream.write(" " * (64 * 1024) + raw)

    def _patch_endpoint(self, project, alias, drop=None, **over):
        self._patch(os.path.join(
            antiphon.peers.peer_dir(project, "claude", alias),
            "endpoint.json"), drop=drop, **over)

    def _patch_session(self, project, alias, drop=None, **over):
        self._patch(os.path.join(
            antiphon.peers.peer_dir(project, "claude", alias),
            "session.json"), drop=drop, **over)

    def _endpoint_path(self, project, alias):
        return os.path.join(antiphon.peers.peer_dir(project, "claude", alias),
                            "endpoint.json")

    def _rewrite_endpoint_text(self, project, alias, edit):
        """Rewrite the endpoint as text, for spellings `json.dump` cannot
        produce: `1.0`, `1e0`, an escaped key, a duplicated key, a 65,000-digit
        token. `edit` maps the current text to the new text."""
        path = self._endpoint_path(project, alias)
        with open(path, encoding="utf-8") as stream:
            text = stream.read()
        with open(path, "w", encoding="utf-8") as stream:
            stream.write(edit(text))

    def _migration_text(self, birth):
        """Turn a current record's text into the 0.4.0 spelling with the given
        birth, leaving the closing brace off for a caller to append a spelling
        of `birth_version` after."""
        def edit(text):
            record = json.loads(text)
            record.pop("process_birth", None)
            record["birth"] = birth
            return json.dumps(record)[:-1]
        return edit

    @staticmethod
    def _own_fingerprint():
        """The rendered spelling a listener's claim answers with, for this
        test process — what `listenerBirth` is compared against."""
        render = getattr(antiphon.peers, "process_fingerprint", None)
        if render is None:
            # The pre-fix tree has no renderer; spell it here so the parity
            # disagreements can be measured before the product changes.
            birth = antiphon.peers._process_birth(os.getpid())
            return f"v1:{birth}" if birth else ""
        return render(os.getpid()) or ""

    @staticmethod
    def _snapshot(project):
        """Every path under the project with its bytes, or its mode when the
        bytes cannot be read — a fixture may deliberately make a file
        unreadable, and that is a state to preserve, not an error."""
        seen = {}
        for root, _dirs, files in os.walk(project):
            for name in sorted(files):
                path = os.path.join(root, name)
                key = os.path.relpath(path, project)
                try:
                    with open(path, "rb") as stream:
                        seen[key] = stream.read()
                except OSError:
                    seen[key] = f"<mode {os.stat(path).st_mode:o}>".encode()
        return seen

    def _both(self, project, alias, digest):
        """Both verdicts from the same state, Node first and provably so.

        `read_peers` prunes as it reads: a record it judges dead is removed,
        and the Python reader runs through it. Measured Python-first, the first
        reader could delete the very record the second was about to be asked
        about — and the second would answer about an absence rather than about
        the state under test, hiding the disagreement.

        The Node reader only reads, so it goes first; and rather than take that
        on trust the project is snapshotted around it. Copying the tree instead
        would be the other way to arrange it, but a fixture that makes a file
        unreadable cannot be copied — that state is exactly what it is testing.
        """
        before = self._snapshot(project)
        node = self._node(project, alias, digest)
        self.assertEqual(self._snapshot(project), before,
                         "the Node reader must not touch what Python is about "
                         "to read; the order only works because it reads")
        return (self._python(project, alias), node)

    def _python(self, project, alias):
        peer = next((p for p in antiphon.peers.read_peers(project, "claude")
                     if p.get("name") == alias), None)
        if peer is None:
            # Not a verdict: there is no record to reach one about. Saying
            # "UNREADY" here would make Python agree with Node by fiat rather
            # than by code, which is the one thing a parity suite must not do.
            return "NO-RECORD"
        # The peer's own owner, exactly as `_automatic_ready` reads it in
        # production. Reading a fixed owner here hid a real divergence: with
        # the endpoint's owner dropped, the harness still found OWNER's proof
        # and answered UNREADY, while production has no key to look one up by.
        verdict = antiphon.automatic_verdict(
            project, "claude", peer,
            antiphon.peers.read_identity_proof(project, peer.get("owner")))
        return verdict or "READY"

    def _node(self, project, alias, digest):
        script = (
            'import { automaticProofVerdict } from "./lib/identity.mjs";'
            'const [d, a, g, pid, birth] = process.argv.slice(-5);'
            'process.stdout.write(String(automaticProofVerdict('
            'd, a, g, Number(pid), birth || undefined)));'
        )
        done = subprocess.run(
            ["node", "--input-type=module", "-e", script, "--",
             project, alias, digest, str(os.getpid()),
             self._own_fingerprint()],
            capture_output=True, text=True, cwd=self.ROOT)
        if done.returncode != 0:
            self.fail("node verdict failed: "
                      + done.stderr.strip()[:400])
        return done.stdout.strip()

    def test_readiness_parity_holds_across_every_fixture(self):
        cases = {
            "proof valid and current": lambda p, a: self._proof(p, self.A),
            # A byte-order mark. The fatal decoder strips it by default and
            # Python keeps it, so the same bytes were a valid record on one
            # side and a parse failure on the other — and with a rotation
            # tombstone beside it, the side that read on was the side that
            # retires.
            "proof carries a byte-order mark": lambda p, a: self._bom(
                antiphon.peers.identity_proof_path(p, self.OWNER),
                self._proof(p, self.A)),
            "session half carries a byte-order mark": lambda p, a: (
                self._proof(p, self.A),
                self._bom(antiphon.peers._session_file(p, "claude", a))),
            "rotated, tombstone carries a byte-order mark": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a),
                self._bom(antiphon.peers.retired_half_path(p, "claude", a))),
            # A key may be spelled two ways, and a pattern that matches text
            # sees only one of them. A pattern also has no idea which object
            # level it is looking at, so an unrelated nested number parted the
            # readers in the other direction.
            "proof spells version with an escape and a float": lambda p, a:
                self._raw(p, self._body(p, self.A).replace(
                    '{"version": 1', '{"ver\\u0073ion": 1.0', 1)),
            "endpoint holds an unrelated nested float": lambda p, a: (
                self._proof(p, self.A),
                self._write(os.path.join(
                    antiphon.peers.peer_dir(p, "claude", a), "endpoint.json"),
                    self._read(os.path.join(
                        antiphon.peers.peer_dir(p, "claude", a),
                        "endpoint.json"))[:-1] + ', "extra": {"pid": 1.0}}')),
            "proof names another session": lambda p, a: self._proof(p, self.B),
            "proof absent": lambda p, a: None,
            "proof wrong kind": lambda p, a: self._proof(p, self.A,
                                                         kind="codex"),
            "proof wrong version": lambda p, a: self._proof(p, self.A,
                                                            version=99),
            "proof malformed digest": lambda p, a: self._proof(
                p, self.A, identity_digest="zz"),
            "proof torn": lambda p, a: self._raw(p, "{"),
            "proof empty": lambda p, a: self._raw(p, ""),
            "session half missing": lambda p, a: (
                self._proof(p, self.A),
                os.unlink(os.path.join(
                    antiphon.peers.peer_dir(p, "claude", a), "session.json"))),
            "session half torn": lambda p, a: (
                self._proof(p, self.A),
                self._write(os.path.join(
                    antiphon.peers.peer_dir(p, "claude", a),
                    "session.json"), "{")),
            # The seven §5 fixtures the first pass omitted. Three of them found
            # real disagreements, two of which were Node saying READY where
            # Python said STRUCTURAL_INVALID — the strongest possible
            # divergence, and invisible while the suite only drove ten cases.
            "proof non-canonical id": lambda p, a: self._raw(
                p, self._body(p, self.A).replace(self.A, "not-a-uuid", 1)),
            "proof version is a float": lambda p, a: self._raw(
                p, self._body(p, self.A, version_literal="1.0")),
            "proof owner key not canonical": lambda p, a: self._proof(
                p, self.A, owner_key="not-an-owner-key"),
            "endpoint owner missing": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, drop="owner")),
            "endpoint owner not canonical": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, owner="not-an-owner-key")),
            "endpoint owner is another owner's": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, owner=self.OTHER_OWNER)),
            # Spec §5 names "owner, digest, pid and address mismatches
            # between the three halves". The digest join was covered on the
            # endpoint side only, and Node had no mirror of it at all — so a
            # half naming another identity read READY there and UNREADY here.
            # L7: `[\s\S]` where Python's OWNER_PATTERN uses `.` without
            # DOTALL, so a newline inside an owner key parted the two readers.
            # M3: `\S` is Unicode-aware in Python and ASCII-only in JS, and
            # the two disagree in both directions. `\u0085` and `\u001c`-`\u001f`
            # are whitespace to Python and not to JS; `\ufeff` is the reverse.
            # One row was Node-destroys-where-Python-refuses. `re.ASCII` is not
            # the fix — it would open a new gap on `\u00a0`.
            "endpoint owner holds a Unicode space": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, owner="1:\u0085")),
            "rotated, owner holds a Unicode space": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a),
                self._patch_endpoint(p, a, owner="1:\u0085")),
            "endpoint owner holds a file separator": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, owner="1:\u001c")),
            "endpoint owner holds a byte-order mark": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, owner="1:\ufeff")),
            "endpoint owner spans a newline": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, owner="1:a\nb")),
            # The alias↔digest binding. Python derives the alias from the
            # digest and requires the record's own `name` to match; Node's
            # mirror had no name check at all, so a half whose name does not
            # derive its digest read as a valid join there — and with a proof
            # naming another session, Node reached PROVED_STALE and destroyed
            # a listener Python was still telling to wait.
            "session half name does not derive its digest": lambda p, a: (
                self._proof(p, self.B),
                self._patch_session(p, a, name="bogus")),
            "session half has no name": lambda p, a: (
                self._proof(p, self.B),
                self._patch_session(p, a, drop="name")),
            "session half has no digest": lambda p, a: (
                self._proof(p, self.A),
                self._patch_session(p, a, drop="identity_digest")),
            "session half digest names another identity": lambda p, a: (
                self._proof(p, self.A),
                self._patch_session(p, a, identity_digest="0" * 64)),
            "session half is not marked automatic": lambda p, a: (
                self._proof(p, self.A),
                self._patch_session(p, a, drop="automatic")),
            "session half id disagrees with its own digest": lambda p, a: (
                self._proof(p, self.A),
                self._patch_session(p, a, session_id=self.B)),
            # The Node mirror of `test_tombstone_every_field_is_load_bearing`.
            # That table drives `automatic_verdict` and nothing else, so ten
            # mutations of the Node validator survived both suites — including
            # two that are destructive and reachable in ordinary operation.
            # Driving the same states through both readers is what closes it.
            "tombstone kind is not claude": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a, kind="codex")),
            "tombstone digest names another identity": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a, digest="0" * 64)),
            "tombstone withdrew a third session": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a, session_id=self.C)),
            # The A→B→A resume, which is the only shape that isolates the
            # current-session guard: the tombstone withdrew A, its digest is
            # A's, and the owner is on A again. Written with a third session
            # the digest binding refuses first and this guard is never reached.
            "the owner came back to the identity it withdrew": lambda p, a: (
                self._proof(p, self.A),
                self._withdrawn(p, a)),
            "tombstone withdrew a non-canonical id": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a, session_id="not-a-uuid")),
            "tombstone owner is not a usable key": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a, owner="not-an-owner-key")),
            "rotated, and the proof is unreadable": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a),
                os.chmod(antiphon.peers.identity_proof_path(p, self.OWNER), 0)),
            # Every tombstone fixture is built on the state a real rotation
            # leaves — proof naming B, tombstone naming A. Written with the
            # proof naming A, the `current_session_id != withdrawn` guard
            # short-circuits first and the field under test is never reached,
            # so the fixture protects nothing.
            "half withdrawn by a rotation": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a)),
            "tombstone from another owner": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a, owner=self.OTHER_OWNER)),
            "tombstone version is a float": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a, version_literal="1.0")),
            "tombstone torn": lambda p, a: (
                self._proof(p, self.B),
                os.unlink(os.path.join(
                    antiphon.peers.peer_dir(p, "claude", a), "session.json")),
                self._write(antiphon.peers.retired_half_path(
                    p, "claude", a), "{")),
            # The Node half of the headline fix had no fixture at all: with the
            # absence guard deleted, a rotated peer whose half is torn, empty
            # or from another owner read PROVED_STALE there and UNREADY here —
            # the destructive direction, and §2 forbids exactly it.
            "tombstone with a torn half": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a),
                self._write(antiphon.peers._session_file(p, "claude", a), "{")),
            "tombstone with an empty half": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a),
                self._write(antiphon.peers._session_file(p, "claude", a), "")),
            "tombstone with a half from another owner": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a),
                self._write(
                    antiphon.peers._session_file(p, "claude", a),
                    json.dumps({"kind": "claude", "name": a,
                                "owner": self.OTHER_OWNER,
                                "session_id": self.A, "automatic": True,
                                "identity_digest":
                                    antiphon.peers.auto_identity(self.A)[1]}))),
            "session half from another owner": lambda p, a: (
                self._proof(p, self.A),
                self._patch_session(p, a, owner=self.OTHER_OWNER)),
            "records padded past the ceiling": lambda p, a: (
                self._proof(p, self.A),
                self._pad(antiphon.peers.identity_proof_path(p, self.OWNER))),
            "padded tombstone after a rotation": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a),
                self._pad(antiphon.peers.retired_half_path(p, "claude", a))),
            # Duplicate keys: Node's `JSON.parse` keeps the last silently,
            # Python's reader refuses the record. The exact-key check cannot
            # see them — duplicates collapse at parse time — so the readers
            # parted on a record neither should accept at all.
            #
            # The version spelling is the wrong key to test it with: the first
            # duplicate trips the float scan, so the fixture passed for a
            # reason that has nothing to do with duplication. A non-numeric
            # key is what isolates it.
            "proof repeats the version key": lambda p, a: self._raw(
                p, self._body(p, self.A).replace(
                    '{"version": 1', '{"version": 1.0, "version": 1', 1)),
            "proof repeats a non-numeric key": lambda p, a: self._raw(
                p, self._body(p, self.A).replace(
                    '"kind": "claude"', '"kind": "codex", "kind": "claude"', 1)),
            "tombstone repeats a non-numeric key": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a),
                self._rewrite(
                    antiphon.peers.retired_half_path(p, "claude", a),
                    lambda text: text.replace(
                        '"kind": "claude"',
                        '"kind": "codex", "kind": "claude"', 1))),
            # Duplicates are refused at every depth on the Python side, and
            # only the object's own level was counted here. Endpoint and
            # session records carry no exact-key rule — they may hold a
            # `birth` or a `transcript` — so a nested object is reachable.
            "session half holds a nested duplicate": lambda p, a: (
                self._proof(p, self.A),
                self._write(antiphon.peers._session_file(p, "claude", a),
                            self._read(antiphon.peers._session_file(
                                p, "claude", a))[:-1]
                            + ', "extra": {"x": 1, "x": 2}}')),
            # And the same name spelled two ways is one name to both parsers.
            "session half repeats a key by escape": lambda p, a: (
                self._proof(p, self.A),
                self._write(antiphon.peers._session_file(p, "claude", a),
                            self._read(antiphon.peers._session_file(
                                p, "claude", a)).replace(
                                    '"owner"', '"\\u006fwner": "x", "owner"',
                                    1))),
            # A decode that refuses is a torn record, not an unreadable one:
            # the fatal decoder throws with a `code`, and a catch that reads
            # the code first called it unreadable — UNKNOWN where Python says
            # STRUCTURAL_INVALID.
            "proof holds an undecodable byte": lambda p, a: (
                self._proof(p, self.A),
                self._corrupt_bytes(
                    antiphon.peers.identity_proof_path(p, self.OWNER))),
            # Invalid UTF-8: Node decodes it to a replacement character and
            # reads on; Python refuses the bytes. A record one reader cannot
            # decode is not one the other may route or retire on.
            "proof carries an extra key": lambda p, a: self._raw(
                p, self._body(p, self.A)[:-1] + ', "note": "hello"}'),
            "tombstone carries an extra key": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a, extra=', "note": "hello"')),
            # --- the fingerprint contract: both readers, one selector ---
            "sibling is the listener's own birth": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, process_birth="v1:" + self._own_birth())),
            "migration pair, same birth": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, drop="process_birth",
                                     birth=self._own_birth(), birth_version=1)),
            "migration pair, version spelled 1.0": lambda p, a: (
                self._proof(p, self.A),
                self._rewrite_endpoint_text(p, a, lambda t:
                    self._migration_text(self._own_birth())(t) + ', "birth_version": 1.0}')),
            "migration pair, version spelled 1e0": lambda p, a: (
                self._proof(p, self.A),
                self._rewrite_endpoint_text(p, a, lambda t:
                    self._migration_text(self._own_birth())(t) + ', "birth_version": 1e0}')),
            "migration pair, version key escaped": lambda p, a: (
                self._proof(p, self.A),
                self._rewrite_endpoint_text(p, a, lambda t:
                    self._migration_text(self._own_birth())(t) + ', "birth\\u005fversion": 1}')),
            "malformed sibling beside a conflicting valid pair (7)": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, process_birth=7,
                                     birth=self._own_birth(), birth_version=1)),
            "malformed sibling beside a conflicting valid pair (null)": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, process_birth=None,
                                     birth=self._own_birth(), birth_version=1)),
            "malformed current sibling beside a valid pair (v1:garbage)": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, process_birth="v1:garbage",
                                     birth=self._own_birth(), birth_version=1)),
            "sibling of a future generation": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, process_birth="v2:whatever")),
            "sibling of a nine-digit generation": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, process_birth="v999999999:" + self._own_birth())),
            "sibling of generation zero": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, process_birth="v0:" + self._own_birth())),
            "sibling of a zero-padded generation": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, process_birth="v01:" + self._own_birth())),
            "sibling shaped but out of range": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, process_birth="v1:Mon Jan 99 99:99:99 2026")),
            "sibling with a trailing NEL": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, process_birth="v1:" + self._own_birth() + "\u0085")),
            "sibling with a leading BOM": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, process_birth="\ufeffv1:" + self._own_birth())),
            "migration birth with a trailing NEL": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, drop="process_birth",
                                     birth=self._own_birth() + "\u0085", birth_version=1)),
            "migration birth with a leading BOM": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, drop="process_birth",
                                     birth="\ufeff" + self._own_birth(), birth_version=1)),
            "no fingerprint at all": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, drop="process_birth")),
            # The bound is lexical and integer-only on both sides, so a long
            # float is a valid record everywhere.
            "an unrelated nested field holds a 21-digit float": lambda p, a: (
                self._proof(p, self.A),
                self._rewrite_endpoint_text(p, a, lambda t:
                    t[:-1] + ', "extra": {"n": ' + "9" * 21 + ".0}}")),
            "an unrelated nested field holds a 21-digit exponent": lambda p, a: (
                self._proof(p, self.A),
                self._rewrite_endpoint_text(p, a, lambda t:
                    t[:-1] + ', "extra": {"n": ' + "9" * 21 + "e0}}")),
        }
        if not self._own_birth():
            self.skipTest("no readable process table: the fingerprint "
                          "fixtures need this process's own birth")
        # One case cannot be compared by equality, and saying so is more
        # honest than bending either side to match. With the endpoint's digest
        # replaced, the record no longer derives its own alias: `read_peers`
        # will not return it at all, so Python has no record to reach a verdict
        # about, while Node — handed the listener's digest directly — answers
        # `null`, meaning "not this contract's record". Both refuse; neither
        # reports READY; there is no shared verdict to be equal to.
        ungovernable = {
            "endpoint digest mismatched": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, identity_digest="0" * 64)),
            "endpoint holds a nested duplicate": lambda p, a: (
                self._proof(p, self.A),
                self._write(os.path.join(
                    antiphon.peers.peer_dir(p, "claude", a), "endpoint.json"),
                    self._read(os.path.join(
                        antiphon.peers.peer_dir(p, "claude", a),
                        "endpoint.json"))[:-1]
                    + ', "extra": {"x": 1, "x": 2}}')),
            "endpoint name does not derive its digest": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, name="bogus")),
            # Node had no mirror of `_scan`'s name-to-directory binding, so an
            # endpoint whose `name` is not the directory it sits in read as a
            # peer there and as nothing at all here. With a rotation tombstone
            # beside it Node reached PROVED_STALE — it retired a listener over
            # a record that, to the other reader, does not exist.
            "rotated, endpoint name is not its directory": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a),
                self._patch_endpoint(p, a, name="bogus")),
            "endpoint torn": lambda p, a: (
                self._proof(p, self.A),
                self._write(os.path.join(
                    antiphon.peers.peer_dir(p, "claude", a),
                    "endpoint.json"), "{")),
            # L2: §5 names pid and address mismatches, and neither had a
            # fixture. Python's `read_peers` filters on kind, pid and address;
            # Node's verdict consulted none of them.
            "endpoint pid dropped": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, drop="pid")),
            "endpoint pid is not a number": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, pid="many")),
            # I5: `int()` accepts a numeric string, an integral float and a
            # bool; Node wants a real integer. Python routed to peers Node
            # would refuse, which is the same file read two ways again.
            # I7: extra keys were ignored, and an ignored key can carry text.
            # Node reads the version's spelling from the source, so a value
            # holding a `"version": 1.0` literal could part the two readers —
            # and a record nobody wrote is not one either should trust. The
            # version field exists so a shape change can be coordinated; until
            # it is bumped, an unknown key means this is not that shape.
            # Both readers reach a verdict on a padded record, so these belong
            # with the equality cases. In `ungovernable` — whose only assertion
            # is "neither says READY" — they were inert: both are non-READY
            # with or without the ceiling, so the fixture written for the
            # ceiling could not detect its removal.
            "endpoint holds an undecodable byte": lambda p, a: (
                self._proof(p, self.A),
                self._corrupt(os.path.join(
                    antiphon.peers.peer_dir(p, "claude", a), "endpoint.json"))),
            "endpoint pid is a numeric string": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, pid=str(os.getpid()))),
            "endpoint pid is a float": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, pid=float(os.getpid()))),
            # No common upper bound: `os.kill` raises OverflowError above the
            # platform's signed int and Node happily reads on.
            "endpoint spells pid with an escape and a float": lambda p, a: (
                self._proof(p, self.A),
                self._write(os.path.join(
                    antiphon.peers.peer_dir(p, "claude", a), "endpoint.json"),
                    self._read(os.path.join(
                        antiphon.peers.peer_dir(p, "claude", a),
                        "endpoint.json")).replace(
                            '"pid": ', '"p\\u0069d": ', 1)
                    .replace('"p\\u0069d": %d' % os.getpid(),
                             '"p\\u0069d": %d.0' % os.getpid(), 1))),
            # A listener's own endpoint must name the listener. Node checked
            # the pid's type and never whose it was, so a record naming a dead
            # or unrelated process read as this listener's own — and with a
            # rotation tombstone beside it, Node retired over a record Python
            # prunes before it can be enumerated at all.
            # The pid is half of a process identity; the birth is the other
            # half, and it is what tells a live process from a recycled number.
            # Node compared the pid alone, so an endpoint left by an earlier
            # process that happens to share this pid read as this listener's
            # own — while Python prunes it before it can be enumerated.
            "sibling names another process's birth": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, process_birth="v1:Thu Jan 1 00:00:00 1970")),
            "rotated, sibling names another birth": lambda p, a: (
                self._proof(p, self.B), self._withdrawn(p, a),
                self._patch_endpoint(p, a, process_birth="v1:Thu Jan 1 00:00:00 1970")),
            "migration pair, other birth": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, drop="process_birth",
                                     birth="Thu Jan 1 00:00:00 1970", birth_version=1)),
            "migration pair, version key duplicated": lambda p, a: (
                self._proof(p, self.A),
                self._rewrite_endpoint_text(p, a, lambda t:
                    self._migration_text(self._own_birth())(t)
                    + ', "birth_version": 2, "birth_version": 1}')),
            "migration pair, version is a 65,000-digit token": lambda p, a: (
                self._proof(p, self.A),
                self._rewrite_endpoint_text(p, a, lambda t:
                    self._migration_text(self._own_birth())(t)
                    + ', "birth_version": ' + "9" * 65_000 + "}")),
            # The bound has to hold at every depth on both sides. Python's
            # parse_int sees every token; Node's lexer has to count digits
            # in nested values too, or a record invalid here is valid there.
            "an unrelated nested field holds a 21-digit integer": lambda p, a: (
                self._proof(p, self.A),
                self._rewrite_endpoint_text(p, a, lambda t:
                    t[:-1] + ', "extra": {"n": ' + "9" * 21 + "}}")),
            "endpoint names a dead process": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, pid=self._reaped_pid())),
            "rotated, endpoint names a dead process": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a),
                self._patch_endpoint(p, a, pid=self._reaped_pid())),
            "endpoint pid is astronomically large": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, pid=10 ** 100)),
            "endpoint pid is a bool": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, pid=True)),
            # `strip()` and `trim()` are not the same set, in both
            # directions: an address of a single U+0085 was empty to one
            # reader and a real address to the other, U+FEFF the reverse.
            "endpoint address is one Unicode space": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, address="\u0085")),
            "endpoint address is a byte-order mark": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, address="\ufeff")),
            "rotated, address is one Unicode space": lambda p, a: (
                self._proof(p, self.B),
                self._withdrawn(p, a),
                self._patch_endpoint(p, a, address="\u0085")),
            "endpoint address dropped": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, drop="address")),
            "endpoint kind is codex": lambda p, a: (
                self._proof(p, self.A),
                self._patch_endpoint(p, a, kind="codex")),
            "endpoint missing": lambda p, a: (
                self._proof(p, self.A),
                os.unlink(os.path.join(
                    antiphon.peers.peer_dir(p, "claude", a),
                    "endpoint.json"))),
        }
        for name, mutate in ungovernable.items():
            with self.subTest(fixture=name):
                with tempfile.TemporaryDirectory() as project:
                    alias, digest = self._peer(project)
                    mutate(project, alias)
                    # The bucket audits its own membership. Four times now a
                    # fixture written for a real divergence has landed here,
                    # where the only claim is "neither says READY" — and both
                    # readers were non-READY with and without the code under
                    # test, so the fixture asserted nothing. A state Python can
                    # still reach a verdict about is comparable, and belongs in
                    # `cases`; only a record it cannot enumerate at all lives
                    # here. Getting that wrong is now a failure, not a silence.
                    # Once, and reused. Calling it twice runs the pruning
                    # reader twice: the first call can delete the record the
                    # second measures, and the second answers about an absence.
                    # That is the very trap `_both` was written to close, and
                    # it came straight back in through calling it again.
                    measured = self._both(project, alias, digest)
                    self.assertEqual(
                        measured[0], "NO-RECORD",
                        f"{name}: Python reaches a verdict here, so the two "
                        "readers can be compared — move this fixture to "
                        "`cases`, where a disagreement is caught")
                    for reader, verdict in zip(("python", "node"), measured):
                        self.assertNotEqual(
                            verdict, "READY",
                            f"{name}: {reader} must not call this routable")
                        # And must not destroy anything over it either. A
                        # record one reader cannot even enumerate is the last
                        # thing the other should retire a listener on, and
                        # "neither says READY" was blind to that.
                        self.assertNotEqual(
                            verdict, "PROVED_STALE",
                            f"{name}: {reader} must not retire on a record "
                            "the other cannot enumerate")

        disagreements = []
        for name, mutate in cases.items():
            with tempfile.TemporaryDirectory() as project:
                alias, digest = self._peer(project)
                mutate(project, alias)
                python, node = self._both(project, alias, digest)
                if python != node:
                    disagreements.append(f"{name}: python={python} node={node}")
        self.assertEqual(disagreements, [],
                         "one file format, two readers, and their agreement is "
                         "enforced here rather than assumed")


class ConfiguredNameTest(unittest.TestCase):
    """Presence and usability are different facts.

    A person who wrote a name meant to be named. Falling through to an
    automatic identity substitutes one silently, which is the same family as
    delivering to the wrong recipient. Absence alone enables automatic
    identity, and empty or whitespace is absence: `explicit_name` documents
    that and `fresh-user.sh` relies on it in ten places.
    """

    SESSION = "8261c119-2c20-4bf4-87ab-f152ac87dbda"
    OTHER = "0199a1b2-2222-7000-8000-00000000000b"

    def _observations(self, project):
        directory = antiphon.peers.observations_dir(project)
        return sorted(os.listdir(directory)) if os.path.isdir(directory) else []

    def _hook(self, project, name):
        # Only ANTIPHON_NAME moves; clearing the whole environment would take
        # PATH with it and the owner-key probe shells out to `ps`.
        with patch.dict(os.environ, {}):
            os.environ.pop("ANTIPHON_NAME", None)
            if name is not None:
                os.environ["ANTIPHON_NAME"] = name
            return antiphon.record_codex_session(project, self.SESSION, None)

    def test_configured_name_absent_empty_and_whitespace_may_observe(self):
        for name in (None, "", "   ", "\t"):
            with self.subTest(configured=name), \
                 tempfile.TemporaryDirectory() as project:
                self._hook(project, name)
                self.assertEqual(len(self._observations(project)), 1,
                                 "absence enables automatic identity")

    def test_configured_name_uppercase_normalizes_and_joins(self):
        with tempfile.TemporaryDirectory() as project:
            self._hook(project, "BUILD")
            self.assertEqual(self._observations(project), [],
                             "'BUILD' normalizes to the valid name 'build'; "
                             "it was never the invalid case")

    def test_configured_name_invalid_creates_no_observation_or_route(self):
        for name in ("Not A Name!", "a" * 40, "büyük"):
            with self.subTest(configured=name), \
                 tempfile.TemporaryDirectory() as project:
                self._hook(project, name)
                self.assertEqual(
                    self._observations(project), [],
                    "a configured-invalid name never falls through to an "
                    "automatic identity")

    def test_configured_name_invalid_withdraws_its_own_legacy_observation(self):
        """An observation records nothing about which environment wrote it, so
        no later predicate can ignore a bug-created one. The hook withdraws its
        own session id durably, and only its own."""
        with tempfile.TemporaryDirectory() as project:
            antiphon.peers.write_observation(project, self.SESSION)
            antiphon.peers.write_observation(project, self.OTHER)
            self.assertEqual(len(self._observations(project)), 2)
            self._hook(project, "Not A Name!")
            remaining = self._observations(project)
            self.assertEqual(len(remaining), 1,
                             "its own stale observation is withdrawn")
            self.assertIn(self.OTHER, remaining[0],
                          "another session's observation is never touched")
            self._hook(project, "Not A Name!")
            self.assertEqual(len(self._observations(project)), 1,
                             "withdrawal is idempotent")


class IdentityProbeBoundsTest(unittest.TestCase):
    """The probe is bounded at the read, not after it.

    `capture_output=True` buffers whatever the child writes and only then
    compares a length, so the cap bounded nothing. A child that keeps writing
    keeps being read.
    """

    def _probe(self, script, cwd=None):
        """Run the real probe against a real child that misbehaves."""
        argv = [sys.executable, "-c", script]
        with patch.object(antiphon, "_claude_identity_argv",
                          return_value=argv, create=True):
            return antiphon._bounded_identity_probe(argv, cwd or os.getcwd())

    def test_identity_probe_bounds_a_flooding_stdout_child(self):
        flood = ("import sys\n"
                 "while True:\n"
                 "    sys.stdout.write('x' * 4096)\n"
                 "    sys.stdout.flush()\n")
        started = time.monotonic()
        result = self._probe(flood)
        elapsed = time.monotonic() - started
        self.assertIsNone(result.text, "an overflowing probe returns nothing")
        self.assertLessEqual(len(result.captured),
                             antiphon.CLAUDE_IDENTITY_STDOUT_CEILING,
                             "captured bytes stay inside the literal ceiling")
        self.assertLess(elapsed, 10, "it returns promptly, not on child exit")
        self.assertIsNotNone(result.returncode, "the child was reaped")

    def test_identity_probe_bounds_a_flooding_stderr_child(self):
        flood = ("import sys\n"
                 "while True:\n"
                 "    sys.stderr.write('e' * 4096)\n"
                 "    sys.stderr.flush()\n")
        result = self._probe(flood)
        self.assertIsNone(result.text)
        self.assertIsNotNone(result.returncode, "the child was reaped")

    def test_identity_probe_kills_and_reaps_a_child_past_the_deadline(self):
        result = self._probe("import time; time.sleep(60)")
        self.assertIsNone(result.text)
        self.assertIsNotNone(result.returncode,
                             "a child past the deadline is killed and reaped, "
                             "never left behind")

    def test_identity_probe_resolves_a_child_under_the_ceiling(self):
        result = self._probe("print('{\"ok\": true}')")
        self.assertEqual((result.text or "").strip(), '{"ok": true}')

    def test_identity_probe_signals_only_the_child_when_isolation_fails(self):
        """When the group could not be created, the signal must not widen.

        Nothing is asserted about descendants here: spec §8 does not promise
        their death in this case, and promising it would be a promise this
        branch cannot keep.
        """
        group_signals = []
        real_popen = antiphon.subprocess.Popen

        def refuse_new_session(*args, **kwargs):
            # `start_new_session` is applied in the child after fork, so the
            # only honest seam is the spawn itself.
            if kwargs.pop("start_new_session", False):
                raise OSError(1, "operation not permitted")
            return real_popen(*args, **kwargs)

        with patch.object(antiphon.os, "killpg",
                          side_effect=lambda *a: group_signals.append(a)), \
             patch.object(antiphon.subprocess, "Popen", refuse_new_session):
            result = self._probe("import time; time.sleep(60)")
        self.assertIsNone(result.text)
        self.assertEqual(group_signals, [],
                         "never widen a signal past a boundary you failed to "
                         "create")
        self.assertIsNotNone(result.returncode, "the child itself was reaped")


class IdentityPrivacyTest(unittest.TestCase):
    """Private shapes never reach a surface a person or an agent reads.

    Redaction runs before truncation, or a cut could leave half a UUID and the
    check that looked for a whole one would pass.
    """

    UUID = "8261c119-2c20-4bf4-87ab-f152ac87dbda"
    DIGEST = "9aa9141f2a5c704b91ef1d2122ad75e67a1ca8be84b7fe119a6edeca9f0b6937"
    OWNER = "4242:v1:Mon Sep  1 00:00:00 2026"
    ALIAS = "auto-tkurihzklryexeppduqsfllv4y"

    def test_identity_privacy_redacts_every_private_shape(self):
        route = "/tmp/antiphon-channel-abc123.sock"
        cases = {
            "canonical uuid": self.UUID,
            "uppercase uuid": self.UUID.upper(),
            "uuid inside a sentence": f"session {self.UUID} moved",
            "uuid in a path": f"/x/{self.UUID}.jsonl",
            "identity digest": self.DIGEST,
            "owner key": self.OWNER,
            "automatic socket route": route,
        }
        cases["digest wrapped in word characters"] = self.DIGEST
        cases["owner key run into a word"] = self.OWNER
        # `zz` rather than `ab`: a word character that is not a hex digit. A
        # 64-run inside a *longer* hex run is deliberately left alone — see
        # the case below — and wrapping the fixture in hex would have been
        # asking for that instead of for the boundary under test.
        for name, secret in cases.items():
            with self.subTest(shape=name):
                for wrapper in ("before {} after", "zz{}zz", "({})"):
                    cleaned = antiphon.redact_private(wrapper.format(secret))
                    self.assertNotIn(secret, cleaned, f"{name} in {wrapper}")
                    self.assertNotIn(secret.lower(), cleaned.lower(),
                                     f"{name} in {wrapper}")

    def test_identity_privacy_leaves_a_longer_hex_run_alone(self):
        """A 64-character window inside a longer hex string is not a digest.

        Redacting it would cut the middle out of an unrelated value — a hash of
        something else, a blob, a key — and hand the reader a corrupted string
        while claiming to have protected something. Nothing on this bridge
        writes a digest inside a longer run, and a reader who would have to
        count characters to extract one is not the leak this guards.
        """
        text = f"ab{self.DIGEST}cd"
        self.assertEqual(antiphon.redact_private(text), text)

    def test_identity_privacy_preserves_alias_and_remedy(self):
        text = (f"{self.ALIAS} is no longer this session; reconnect to be "
                f"reachable (session {self.UUID})")
        cleaned = antiphon.redact_private(text)
        self.assertIn(self.ALIAS, cleaned, "the public alias is the useful half")
        self.assertIn("reconnect", cleaned, "the remedy survives")
        self.assertNotIn(self.UUID, cleaned)

    def test_identity_privacy_runs_before_truncation(self):
        """A cut first would leave a fragment the whole-shape check misses."""
        tail = f"trailing {self.UUID}"
        text = "x" * 190 + tail
        cleaned = antiphon.redact_private(text, limit=200)
        self.assertLessEqual(len(cleaned), 200)
        self.assertNotIn(self.UUID[:20], cleaned,
                         "no fragment of a session id survives the cut")

    def test_identity_privacy_preserves_the_refusal_class(self):
        refusal = antiphon._ClassifiedRefusal(
            f"not delivered: {self.UUID} moved", "no-peer")
        cleaned = antiphon.redact_refusal(refusal)
        self.assertEqual(cleaned.refusal_class, "no-peer",
                         "redaction must not cost the class a caller acts on")
        self.assertNotIn(self.UUID, str(cleaned))

    # ---- the six surfaces a route-bearing failure actually reaches ----

    @contextlib.contextmanager
    def project(self):
        with tempfile.TemporaryDirectory() as project:
            with patch.object(antiphon, "project_dir", return_value=project):
                yield project

    def test_identity_privacy_a_queue_refusal_is_redacted_before_it_is_cut(self):
        """`codex queue` writes its own stderr, and this bridge prints it. The
        cut is 200 characters, so a truncation taken first leaves the head of a
        session id behind — a fragment no whole-shape check would catch."""
        noise = "x" * 180
        stderr = f"{noise} thread {self.UUID} is not running"
        with patch.object(antiphon.subprocess, "run", return_value=SimpleNamespace(
                returncode=1, stdout="", stderr=stderr)):
            ok, detail = antiphon._queue_codex(self.UUID, "hello")
        self.assertFalse(ok)
        self.assertLessEqual(len(str(detail)), 200)
        self.assertNotIn(self.UUID[:8], str(detail),
                         "not even the head of a session id survives the cut")
        self.assertEqual(detail.refusal_class, "transport",
                         "redaction must not cost the class")

    def test_identity_privacy_the_stop_hook_never_prints_a_private_shape(self):
        """The Stop hook prints the refusal verbatim on stderr, where the
        person sitting at the terminal reads it."""
        refusal = antiphon._ClassifiedRefusal(
            f"not delivered: {self.DIGEST} moved to {self.UUID}", "no-peer")
        with tempfile.TemporaryDirectory() as project:
            transcript = os.path.join(project, "transcript.jsonl")
            with open(transcript, "w", encoding="utf-8") as f:
                f.write("\n".join([
                    claude_prompt("ask", uuid="U1"),
                    claude_assistant("@codex hello"),
                ]) + "\n")
            printed = io.StringIO()
            with patch.object(antiphon, "send_to_codex",
                              return_value=(False, refusal)), \
                 patch.object(antiphon.sys, "stdin", io.StringIO(json.dumps(
                     {"cwd": project, "transcript_path": transcript}))), \
                 contextlib.redirect_stderr(printed):
                antiphon.push("codex")
        words = printed.getvalue()
        self.assertIn("delivery failed", words, words)
        self.assertNotIn(self.UUID, words)
        self.assertNotIn(self.DIGEST, words)

    def test_identity_privacy_a_startup_refusal_never_echoes_the_owner_key(self):
        """The session-recording refusal is printed once per turn at startup.
        `write_session` names the key it rejected, and that key is a pid and a
        process start time — this session's own, not a peer's to publish."""
        with self.project() as project:
            antiphon.peers.register(project, "claude", "ui", "/tmp/ui.sock",
                                    owner_key=antiphon.peers.owner_key())
            printed = io.StringIO()
            with patch.dict(os.environ, {"ANTIPHON_NAME": "ui"}), \
                 patch.object(antiphon.peers, "owner_key",
                              return_value=self.OWNER.replace("4242", "0")), \
                 contextlib.redirect_stderr(printed):
                antiphon.record_claude_session(project, self.UUID, "/tmp/t.jsonl")
        words = printed.getvalue()
        self.assertIn("invalid owner key", words, words)
        self.assertNotIn("00:00:00 2026", words,
                         "the process start time is half the owner key")

    def test_identity_privacy_status_never_prints_a_private_shape(self):
        """Status is the surface people paste into an issue."""
        with self.project() as project:
            alias, digest = antiphon.peers.auto_identity(self.UUID)
            antiphon.peers.register(
                project, "claude", alias,
                antiphon.claude_socket_path(project, alias),
                identity_digest=digest, mode="initial")
            printed = io.StringIO()
            with contextlib.redirect_stdout(printed):
                antiphon.status()
        words = printed.getvalue()
        self.assertNotIn(self.UUID, words)
        self.assertNotIn(digest, words)
        self.assertNotIn("antiphon-channel-", words)

    def test_identity_privacy_doctor_hides_an_automatic_route(self):
        """An automatic peer's socket is derived from its alias, so printing it
        publishes a route nobody can act on: the remedy is a restart, never a
        path. An explicitly named peer keeps its path, which is the one thing
        that makes `remove it` actionable."""
        with self.project() as project:
            auto, digest = antiphon.peers.auto_identity(self.UUID)
            live = [
                # `automatic: True` is what makes this an automatic record.
                # The fixture leaned on the `auto-` prefix, which is a public
                # name anyone may configure — and doctor was reading identity
                # off that shape rather than off the marker.
                {"kind": "claude", "name": auto, "automatic": True,
                 "identity_digest": digest,
                 "address": antiphon.claude_socket_path(project, auto)},
                {"kind": "claude", "name": "ui",
                 "address": antiphon.claude_socket_path(project, "ui")},
            ]
            printed = io.StringIO()
            report = antiphon._Report()
            with patch.object(antiphon, "_probe_channel",
                              return_value=antiphon.Probe(errno.ECONNREFUSED,
                                                          False)), \
                 contextlib.redirect_stdout(printed):
                antiphon._doctor_channel(report, project, live)
        lines = printed.getvalue().splitlines()
        automatic = [line for line in lines if auto in line]
        explicit = [line for line in lines if '"ui"' in line]
        self.assertTrue(automatic, printed.getvalue())
        self.assertTrue(explicit, printed.getvalue())
        for line in automatic:
            self.assertNotIn("antiphon-channel-", line,
                             "an automatic route is not a remedy")
            self.assertIn("restart", line, line)
        for line in explicit:
            self.assertIn("antiphon-channel-", line,
                          "an explicit peer's path is actionable for it")

    def test_identity_privacy_a_resolver_refusal_keeps_its_class(self):
        """`send_to_claude` hands the resolver's refusal straight back to the
        MCP tool and to the Stop hook. Redacting it there rather than trusting
        every future resolver branch to stay clean is the point of a central
        redactor — and the class is what a caller acts on, so it must survive."""
        refusal = antiphon._ClassifiedRefusal(
            f"not delivered: nothing holds {self.UUID}", "no-peer")
        with tempfile.TemporaryDirectory() as project:
            with patch.object(antiphon, "_resolve_target",
                              return_value=antiphon.ResolvedTarget(
                                  None, refusal, "refusal")):
                ok, detail = antiphon.send_to_claude(project, "hi")
        self.assertFalse(ok)
        self.assertNotIn(self.UUID, str(detail))
        self.assertEqual(detail.refusal_class, "no-peer")

    def test_identity_privacy_redaction_parity_holds_across_both_languages(self):
        """Two redactors, one contract. The Node channel prints its own
        refusals and never crosses back into Python to do it, so a shape only
        one side removes is a shape that reaches a surface on the other."""
        route = "/tmp/antiphon-channel-a561aecdef4cc7b9f794.sock"
        cases = {
            "canonical uuid": f"session {self.UUID} moved",
            "uppercase uuid": f"session {self.UUID.upper()} moved",
            "identity digest": f"digest {self.DIGEST} refused",
            "owner key": f"invalid owner key '{self.OWNER}': expected a pid",
            "automatic route": f"could not clear {route}",
            "the alias survives": f"{self.ALIAS} is not this session",
            "the remedy survives": "restart that Claude session",
            # `\b` and `\d` are Unicode-aware in a Python `str` pattern and
            # ASCII-only in a JS RegExp. A private shape glued to a non-ASCII
            # letter therefore survived Python's redactor and not Node's —
            # and Python is the side that prints to a person's terminal.
            # `\b` asks whether a word character sits beside a word
            # character, which is the wrong question for a hex run and for a
            # key that starts with digits: wrapped in letters, the whole
            # private value passed through untouched — in both languages, so
            # parity agreed on the wrong answer.
            "digest wrapped in word characters": f"zz{self.DIGEST}zz refused",
            "owner key run into a word": f"x{self.OWNER} refused",
            "owner key after a non-ASCII letter": f"iş{self.OWNER} refused",
            "digest after a non-ASCII letter": f"iş{self.DIGEST} refused",
            "digest before a non-ASCII letter": f"{self.DIGEST}ş refused",
            "digest wrapped in word characters": f"zz{self.DIGEST}zz refused",
            "owner key run into a word": f"x{self.OWNER} refused",
            "digest inside a longer hex run": f"ab{self.DIGEST}cd refused",
        }
        script = (
            'import { redactPrivate } from "./lib/identity.mjs";'
            'process.stdout.write(JSON.stringify('
            'JSON.parse(process.argv[process.argv.length - 1])'
            '.map((t) => redactPrivate(t))));'
        )
        done = subprocess.run(
            ["node", "--input-type=module", "-e", script, "--",
             json.dumps(list(cases.values()))],
            capture_output=True, text=True,
            cwd=os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
        if done.returncode != 0:
            self.fail("node redaction failed: " + done.stderr.strip()[:400])
        node = json.loads(done.stdout)
        for (name, text), got in zip(cases.items(), node):
            with self.subTest(shape=name):
                self.assertEqual(antiphon.redact_private(text), got,
                                 f"{name}: the two redactors disagree")

    def test_identity_privacy_doctor_queue_reports_an_aggregate(self):
        """A truncated session id is still session identity. The queue note
        counts the threads instead of naming any of them."""
        import sqlite3
        second = "7f3a91c2-1111-4222-8333-444455556666"
        with tempfile.TemporaryDirectory() as project:
            db = os.path.join(project, "queue_0.sqlite")
            con = sqlite3.connect(db)
            con.execute("CREATE TABLE queued_items (thread_id TEXT)")
            con.executemany("INSERT INTO queued_items VALUES (?)",
                            [(self.UUID,), (self.UUID,), (second,)])
            con.commit()
            con.close()
            rollouts = [os.path.join(project, f"rollout-{self.UUID}.jsonl"),
                        os.path.join(project, f"rollout-{second}.jsonl")]
            printed = io.StringIO()
            report = antiphon._Report()
            with patch.object(antiphon, "CODEX_QUEUE_DBS", db), \
                 patch.object(antiphon, "codex_rollout_files",
                              return_value=rollouts), \
                 patch.object(antiphon, "codex_thread_alive", return_value=False), \
                 contextlib.redirect_stdout(printed):
                antiphon._doctor_codex_queue(report, project)
        words = printed.getvalue()
        self.assertNotIn(self.UUID[:8], words, words)
        self.assertNotIn(second[:8], words, words)
        self.assertRegex(words, r"3 message\(s\).*2 project threads not proved running")


class ReconnectNoticeTest(unittest.TestCase):
    """After a rotation the terminal is unreachable by automatic identity until
    a fresh endpoint exists, and every surface has to say so.

    The proof deliberately outlives endpoints, which is the only reason there is
    anything to name here: in the reconnect window B is the current identity and
    owns no peer record at all, so a lookup finds nothing and only the read-only
    inventory can answer. What it renders is the public alias and the remedy —
    never the host session id, the digest or the route.
    """

    A = "8261c119-2c20-4bf4-87ab-f152ac87dbda"
    B = "0199a1b2-2222-7000-8000-00000000000b"

    def _owner(self):
        """This process's own current-generation key, so liveness is positive."""
        owner = antiphon.peers.owner_key()
        self.assertIsNotNone(owner, "the test needs a real current owner key")
        return owner

    def _rotated(self, project):
        """The window itself: A served, B is current, and B has no endpoint."""
        owner = self._owner()
        alias_a, digest_a = antiphon.peers.auto_identity(self.A)
        antiphon.peers.register(project, "claude", alias_a,
                                os.path.join(project, alias_a + ".sock"),
                                pid=os.getpid(), owner_key=owner,
                                identity_digest=digest_a, mode="initial")
        antiphon.peers.write_session(project, "claude", alias_a, self.A,
                                     f"/t/{alias_a}.jsonl", owner,
                                     digest_a, True)
        antiphon.peers.write_identity_proof(project, owner, self.A, digest_a)
        # The host rotates and B's first hook commits. The listener serving A
        # then withdraws its own endpoint, which is what leaves zero automatic
        # peers behind.
        alias_b, digest_b = antiphon.peers.auto_identity(self.B)
        antiphon.peers.rotate_identity_proof(project, owner, self.B, digest_b)
        antiphon.peers.unregister(project, "claude", alias_a, pid=os.getpid())
        return owner, alias_a, alias_b, digest_b

    def test_reconnect_notice_names_the_alias_and_remedy_after_rotation(self):
        with tempfile.TemporaryDirectory() as project:
            _owner, alias_a, alias_b, digest_b = self._rotated(project)
            self.assertEqual(
                [p for p in antiphon.peers.read_peers(project, "claude")], [],
                "the window under test is the one with zero automatic peers")
            with patch.object(antiphon, "project_dir", return_value=project):
                out = io.StringIO()
                with contextlib.redirect_stdout(out):
                    antiphon.status()
                status = out.getvalue()
                out = io.StringIO()
                with contextlib.redirect_stdout(out):
                    antiphon.doctor()
                doctor = out.getvalue()
        for where, words in (("status", status), ("doctor", doctor)):
            with self.subTest(surface=where):
                self.assertIn(alias_b, words,
                              "the current identity is named by its alias")
                self.assertRegex(words, r"(?i)reconnect",
                                 "the remedy is actionable, not a diagnosis")
                self.assertNotIn(alias_a, words,
                                 "the outgrown alias is not a peer any more")
                self.assertNotIn(self.B, words, "no host session id")
                self.assertNotIn(digest_b, words, "no identity digest")
                self.assertNotIn("antiphon-channel-", words, "no route")

    def test_reconnect_notice_mixed_version_record_fails_closed(self):
        """A proof written under a legacy or future owner-key generation has no
        reproducible fingerprint here, so its owner is `unknown` — never live.
        It is counted, never rendered as an addressable alias, and never
        rewritten into the current generation to make it renderable."""
        legacy = "4242:Mon Sep  1 00:00:00 2026"      # no generation at all
        with tempfile.TemporaryDirectory() as project:
            alias, digest = antiphon.peers.auto_identity(self.B)
            antiphon.peers.write_identity_proof(project, legacy, self.B, digest)
            path = antiphon.peers.identity_proof_path(project, legacy)
            before = pathlib.Path(path).read_bytes()
            with patch.object(antiphon, "project_dir", return_value=project):
                out = io.StringIO()
                with contextlib.redirect_stdout(out):
                    antiphon.status()
                status = out.getvalue()
                out = io.StringIO()
                with contextlib.redirect_stdout(out):
                    antiphon.doctor()
                doctor = out.getvalue()
            after = pathlib.Path(path).read_bytes()
        self.assertEqual(before, after,
                         "a read-only surface never rewrites a proof")
        for where, words in (("status", status), ("doctor", doctor)):
            with self.subTest(surface=where):
                self.assertNotIn(alias, words,
                                 "an owner that cannot be proved live is never "
                                 "rendered as an addressable alias")
                self.assertRegex(
                    words, r"(?i)1 automatic Claude identity",
                    "it is counted, so a reader is not told a confident zero")
        # An owner that cannot be proved live is evidence of nothing, so the
        # line is a note. A `✗` here would move doctor's exit code on a state
        # nobody can act on, which is the kind people learn to ignore. The
        # unrelated ✗ lines a bare temp project earns are not this assertion's
        # business, so the prefix is checked rather than the exit code.
        counted = [line for line in doctor.splitlines()
                   if "could not be proved live" in line]
        self.assertTrue(counted, doctor)
        for line in counted:
            self.assertTrue(line.startswith("·"), line)


class ProofLifecycleSurfaceTest(unittest.TestCase):
    """Reclamation belongs to the write path, and to nothing else.

    `status` and `doctor` exist to explain a quiet bridge without changing it.
    A read that collected would remove the record it was about to explain, and
    the operator would be told a confident zero by the very command they ran to
    find out what was there.
    """

    A = "8261c119-2c20-4bf4-87ab-f152ac87dbda"
    B = "0199a1b2-2222-7000-8000-00000000000b"

    @staticmethod
    def _dead_pid():
        child = subprocess.Popen([sys.executable, "-c", "pass"])
        child.wait()
        return child.pid

    def test_proof_lifecycle_read_only_surfaces_reclaim_nothing(self):
        with tempfile.TemporaryDirectory() as project:
            dead = f"{self._dead_pid()}:v1:Mon Sep  1 00:00:00 2026"
            _alias, digest = antiphon.peers.auto_identity(self.A)
            antiphon.peers.write_identity_proof(project, dead, self.A, digest)
            path = antiphon.peers.identity_proof_path(project, dead)
            before = pathlib.Path(path).read_bytes()
            with patch.object(antiphon, "project_dir", return_value=project):
                with contextlib.redirect_stdout(io.StringIO()):
                    antiphon.status()
                    antiphon.doctor()
                # The resolver reads proofs on every send decision, and it is
                # the hottest read path there is.
                antiphon._resolve_target(project, "claude", None)
            self.assertTrue(os.path.exists(path),
                            "a read-only surface never collects a proof, not "
                            "even one whose owner is proved dead")
            self.assertEqual(before, pathlib.Path(path).read_bytes(),
                             "nor rewrites one")

    def test_proof_lifecycle_the_real_hook_collects(self):
        """The whole point of putting the sweep on `rotate_identity_proof` is
        that production reaches it. Driven through `record_claude_session` —
        the Claude hook's own entry point — rather than the rotation helper,
        because a caller that exists only in a test collects nothing."""
        with tempfile.TemporaryDirectory() as project:
            dead = f"{self._dead_pid()}:v1:Mon Sep  1 00:00:00 2026"
            _alias, digest_a = antiphon.peers.auto_identity(self.A)
            antiphon.peers.write_identity_proof(project, dead, self.A, digest_a)
            stale = antiphon.peers.identity_proof_path(project, dead)
            self.assertTrue(os.path.exists(stale))
            env = {k: v for k, v in os.environ.items() if k != "ANTIPHON_NAME"}
            with patch.dict(os.environ, env, clear=True), \
                 contextlib.redirect_stderr(io.StringIO()):
                antiphon.record_claude_session(project, self.B, "/t/b.jsonl")
            self.assertFalse(os.path.exists(stale),
                             "the hook production runs is what collects")


class TornProofDoesNotWedgeTheHookTest(unittest.TestCase):
    """One unreadable byte sequence must not cost a project its identity.

    The rotation commits first, so the old alias correctly stops resolving. If
    the sweep then raises, the hook's own `except Exception` catches it before
    `write_session` — the new identity never becomes routable, and because the
    sweep bailed before advancing its cursor, every later hook repeats it. The
    terminal is unnamed from then on, and nothing anywhere says why.
    """

    B = "0199a1b2-2222-7000-8000-00000000000b"

    def test_a_torn_proof_leaves_the_new_identity_routable(self):
        with tempfile.TemporaryDirectory() as project:
            torn = antiphon.peers.identity_proof_path(
                project, f"{os.getpid()}:v1:Tue Sep  2 00:00:00 2026")
            os.makedirs(os.path.dirname(torn), exist_ok=True)
            with open(torn, "wb") as stream:
                stream.write(b'{"kind": "\xff\xfe\x00bad"}')
            # The channel registers the endpoint; the hook writes the half.
            # An automatic half requires its endpoint, so without this the hook
            # would refuse for a reason that has nothing to do with the wedge.
            alias, digest = antiphon.peers.auto_identity(self.B)
            antiphon.peers.register(
                project, "claude", alias, os.path.join(project, alias + ".sock"),
                pid=os.getpid(), owner_key=antiphon.peers.owner_key(),
                identity_digest=digest, mode="initial")
            env = {k: v for k, v in os.environ.items() if k != "ANTIPHON_NAME"}
            printed = io.StringIO()
            with patch.dict(os.environ, env, clear=True), \
                 contextlib.redirect_stderr(printed):
                recorded = antiphon.record_claude_session(
                    project, self.B, "/t/b.jsonl")
            self.assertTrue(recorded, printed.getvalue())
            self.assertTrue(
                os.path.exists(
                    antiphon.peers._session_file(project, "claude", alias)),
                "the new session half is written, so the alias can be joined")
            self.assertNotIn("could not be joined", printed.getvalue())


class RetireControlWireTest(unittest.TestCase):
    """The retire control has to be recognised as a control, or it is nothing.

    The listener validates the envelope on magic, version, action, alias and
    nonce. A payload that misses the magic never reaches that branch at all: it
    falls through to the content check and is refused as malformed content, so
    the wakeup this bridge sends after every rotation has been landing in the
    void. That is not authentication — there is no shared secret here — it is
    the shape that makes the message legible as its own action.
    """

    def _sent(self, alias="auto-tkurihzklryexeppduqsfllv4y"):
        captured = {}

        class _Socket:
            def settimeout(self, _): pass
            def connect(self, _): pass
            def sendall(self, payload): captured["raw"] = payload
            def close(self): pass

        with patch.object(antiphon.socket, "socket", return_value=_Socket()):
            antiphon._retire_control("/tmp/p", alias, "/tmp/p.sock")
        return json.loads(captured["raw"].decode())

    def test_the_retire_control_carries_the_envelope_the_listener_validates(self):
        payload = self._sent()
        self.assertEqual(payload.get("control"), antiphon.CHANNEL_CONTROL,
                         "without the magic the listener never reaches the "
                         "control branch")
        self.assertEqual(payload.get("version"),
                         antiphon.CHANNEL_CONTROL_VERSION)
        self.assertEqual(payload.get("action"), "identity-retire")
        self.assertEqual(payload.get("alias"),
                         "auto-tkurihzklryexeppduqsfllv4y")
        self.assertRegex(str(payload.get("nonce")), r"^[A-Za-z0-9_-]{1,128}$",
                         "the nonce is part of the validated shape")
        self.assertNotIn("content", payload,
                         "content-free: a control is not a message")

    def test_the_retire_control_is_validated_on_exactly_these_fields(self):
        """Read from `channel.mjs` rather than restated here. Two literals in
        two languages drift silently; this fails the moment they do."""
        node = read_source("lib", "channel.mjs")
        branch = node[node.index('payload?.control === CHANNEL_CONTROL'):]
        branch = branch[:branch.index("if (typeof payload.content")]
        for field in ("version", "action", "alias", "nonce"):
            self.assertIn(field, branch, f"the listener validates {field}")
        self.assertIn('"identity-retire"', branch,
                      "the listener recognises the action this side sends")


class DoctorRemedyMatchesTheVerdictTest(unittest.TestCase):
    """A remedy that does not repair the state is worse than none.

    `UNREADY` is the state every automatic channel passes through before its
    first Stop hook: the hook is about to make it ready. Telling that operator
    to reconnect restarts the identical wait, and the same remedy was being
    appended to `UNKNOWN` — an unreadable proof, which a reconnect does not
    repair — and to `STRUCTURAL_INVALID`. Only a rotation is fixed by
    reconnecting, and only `PROVED_STALE` names one.
    """

    B = "0199a1b2-2222-7000-8000-00000000000b"

    def _doctor_line(self, project, alias):
        out = io.StringIO()
        report = antiphon._Report()
        with contextlib.redirect_stdout(out):
            antiphon._doctor_peers(report, project)
        return next((line for line in out.getvalue().splitlines()
                     if alias in line), out.getvalue())

    def test_doctor_remedy_a_channel_before_its_first_hook_is_not_told_to_reconnect(self):
        with tempfile.TemporaryDirectory() as project:
            alias, digest = antiphon.peers.auto_identity(self.B)
            antiphon.peers.register(
                project, "claude", alias,
                os.path.join(project, alias + ".sock"),
                pid=os.getpid(), owner_key=antiphon.peers.owner_key(),
                identity_digest=digest, mode="initial")
            antiphon.peers.write_identity_proof(
                project, antiphon.peers.owner_key(), self.B, digest)
            line = self._doctor_line(project, alias)
        self.assertNotIn(antiphon.RECONNECT_REMEDY, line, line)
        self.assertIn("waiting for its first turn", line, line)

    def test_doctor_remedy_only_a_rotation_earns_the_reconnect(self):
        with tempfile.TemporaryDirectory() as project:
            with patch.object(antiphon, "automatic_verdict",
                              return_value="PROVED_STALE"):
                alias, digest = antiphon.peers.auto_identity(self.B)
                antiphon.peers.register(
                    project, "claude", alias,
                    os.path.join(project, alias + ".sock"),
                    pid=os.getpid(), owner_key=antiphon.peers.owner_key(),
                    identity_digest=digest, mode="initial")
                line = self._doctor_line(project, alias)
        self.assertIn(antiphon.RECONNECT_REMEDY, line, line)


class DoctorFingerprintNotesTest(unittest.TestCase):
    """Two records doctor has to name, read-only, with the remedy by kind.

    A record still in the 0.4.0 migration spelling stays prunable by a 0.3.x
    reader until its owner rewrites it — a Claude session by reconnecting (an
    old listener's reassert is refused without writing), a Codex session by
    restarting. And an automatic Claude record without a current fingerprint
    is UNREADY for a reason that is not the bootstrap one: no current
    listener can be serving it as its own, and the operator must be told
    that rather than "waiting for its first turn".
    """

    A = "8261c119-2c20-4bf4-87ab-f152ac87dbda"

    def _doctor(self, project):
        out = io.StringIO()
        report = antiphon._Report()
        with contextlib.redirect_stdout(out):
            antiphon._doctor_peers(report, project)
        return out.getvalue()

    @staticmethod
    def _rewrite_endpoint(project, kind, name, mutate):
        path = antiphon.peers._peer_file(project, kind, name)
        with open(path, encoding="utf-8") as stream:
            record = json.load(stream)
        mutate(record)
        with open(path, "w", encoding="utf-8") as stream:
            json.dump(record, stream)

    def _register_migration_spelling(self, project, kind, name):
        """What 0.4.0-on-main wrote: `birth` under the canon beside the
        integer `birth_version: 1`, and no sibling."""
        owner = antiphon.peers.owner_key()
        address = None if kind == "codex" else os.path.join(project, name + ".sock")
        ok, detail = antiphon.peers.register(project, kind, name, address,
                                             pid=os.getpid(), owner_key=owner)
        self.assertTrue(ok, detail)
        birth = antiphon.peers._process_birth(os.getpid())
        if not birth:
            self.skipTest("no readable process table")

        def to_migration(record):
            record.pop("process_birth", None)
            record["birth"] = birth
            record["birth_version"] = 1
        self._rewrite_endpoint(project, kind, name, to_migration)

    def _register_automatic(self, project, kind="claude"):
        alias, digest = antiphon.peers.auto_identity(self.A)
        owner = antiphon.peers.owner_key()
        address = None if kind == "codex" else os.path.join(project, alias + ".sock")
        ok, detail = antiphon.peers.register(
            project, kind, alias, address, pid=os.getpid(), owner_key=owner,
            identity_digest=digest, mode="initial" if kind == "claude" else None)
        self.assertTrue(ok, detail)
        if kind == "claude":
            antiphon.peers.write_identity_proof(project, owner, self.A, digest)
        return alias

    def test_doctor_names_a_record_an_old_reader_may_still_prune(self):
        """Risk, not diagnosis: doctor cannot see whether such a reader is
        running. The remedy is by kind."""
        with tempfile.TemporaryDirectory() as project:
            self._register_migration_spelling(project, "claude", "ui")
            self._register_migration_spelling(project, "codex", "x")
            report = self._doctor(project)
        self.assertIn("peer claude/ui: fingerprint in the 0.4.0 spelling; a 0.3.x "
                      "reader, if one is still running, prunes it until this "
                      "Claude session reconnects", report)
        self.assertIn("peer codex/x: fingerprint in the 0.4.0 spelling; a 0.3.x "
                      "reader, if one is still running, prunes it until that "
                      "Codex session restarts", report)

    def test_doctor_names_an_unready_record_that_carries_no_current_fingerprint(self):
        """UNREADY has a bootstrap meaning — waiting for its first turn — and
        this record is not that. Say what it is, and say only that: the
        bootstrap line must not appear beside it."""
        with tempfile.TemporaryDirectory() as project:
            alias = self._register_automatic(project)
            self._rewrite_endpoint(project, "claude", alias,
                                   lambda r: r.update(process_birth="v1:garbage"))
            report = self._doctor(project)
        self.assertIn(f"peer claude/{alias}: endpoint carries no current fingerprint, "
                      "so no current listener can be serving it as its own; "
                      "reconnect the Claude session", report)
        self.assertNotIn(f"peer claude/{alias}: live, waiting for its first turn", report)

    def test_doctor_gives_no_claude_remedy_to_an_automatic_codex_record(self):
        """Codex records carry `automatic` too, and the verdict does not
        govern them. A fingerprint-less automatic Codex record gets the
        migration-risk note at most, never 'reconnect the Claude session'."""
        with tempfile.TemporaryDirectory() as project:
            alias = self._register_automatic(project, kind="codex")
            self._rewrite_endpoint(project, "codex", alias,
                                   lambda r: r.update(process_birth="v1:garbage"))
            report = self._doctor(project)
        self.assertIn(f"codex/{alias}", report, "the record is listed at all")
        self.assertNotIn("reconnect the Claude session", report)
        self.assertNotIn("no current listener can be serving it", report)


class DoctorAutomaticIsStructuralTest(unittest.TestCase):
    """`auto-` is a public prefix, not a fact about a record.

    The alias grammar allows `auto-...` as a configured name, and this project
    refuses everywhere else to read identity off a shape — that is the whole
    argument for the endpoint's own `automatic` marker. Doctor inferred it from
    the prefix, so an operator who set `ANTIPHON_NAME=auto-...` had their
    socket path hidden and was offered a remedy for a rotation that cannot
    happen to them.
    """

    ALIAS = "auto-tkurihzklryexeppduqsfllv4y"

    def test_doctor_automatic_an_explicit_peer_named_auto_keeps_its_path(self):
        with tempfile.TemporaryDirectory() as project:
            live = [{"kind": "claude", "name": self.ALIAS,
                     "address": antiphon.claude_socket_path(project,
                                                            self.ALIAS)}]
            printed = io.StringIO()
            report = antiphon._Report()
            with patch.object(antiphon, "_probe_channel",
                              return_value=antiphon.Probe(errno.ECONNREFUSED,
                                                          False)), \
                 contextlib.redirect_stdout(printed):
                antiphon._doctor_channel(report, project, live)
            line = next(l for l in printed.getvalue().splitlines()
                        if self.ALIAS in l)
        self.assertIn("antiphon-channel-", line,
                      "no `automatic` marker on the record, so this is an "
                      "explicitly named peer and its path is actionable")

    def test_doctor_automatic_a_real_automatic_peer_still_hides_its_route(self):
        with tempfile.TemporaryDirectory() as project:
            digest = antiphon.peers.auto_identity(
                "8261c119-2c20-4bf4-87ab-f152ac87dbda")[1]
            live = [{"kind": "claude", "name": self.ALIAS, "automatic": True,
                     "identity_digest": digest,
                     "address": antiphon.claude_socket_path(project,
                                                            self.ALIAS)}]
            printed = io.StringIO()
            report = antiphon._Report()
            with patch.object(antiphon, "_probe_channel",
                              return_value=antiphon.Probe(errno.ECONNREFUSED,
                                                          False)), \
                 contextlib.redirect_stdout(printed):
                antiphon._doctor_channel(report, project, live)
            line = next(l for l in printed.getvalue().splitlines()
                        if self.ALIAS in l)
        self.assertNotIn("antiphon-channel-", line)
        self.assertIn("restart", line)


class ProbeDescendantTerminationTest(unittest.TestCase):
    """Isolation is promised to kill descendants; it has to actually do it.

    The group signal recomputed the group from the leader's pid every time. A
    leader that exits on SIGTERM therefore takes its own group id with it: the
    follow-up `getpgid` raises, the SIGKILL is swallowed, and a descendant that
    ignores SIGTERM outlives the probe. The pid is the group id only while the
    leader is alive, so it has to be captured when the group is created.
    """

    CHILD = (
        "import os, signal, subprocess, sys, time\n"
        "grandchild = subprocess.Popen([sys.executable, '-c',\n"
        "    \"import signal, time\\n\"\n"
        "    \"signal.signal(signal.SIGTERM, signal.SIG_IGN)\\n\"\n"
        "    \"import sys; sys.stdout.write(str(__import__('os').getpid()))\\n\"\n"
        "    \"sys.stdout.flush()\\n\"\n"
        "    \"time.sleep(60)\\n\"],\n"
        "    stdout=open(os.environ['ANTIPHON_TEST_PIDFILE'], 'w'))\n"
        "time.sleep(60)\n"
    )

    def test_identity_probe_kills_a_descendant_that_ignores_sigterm(self):
        with tempfile.TemporaryDirectory() as scratch:
            pidfile = os.path.join(scratch, "grandchild.pid")
            argv = [sys.executable, "-c", self.CHILD]
            env = {**os.environ, "ANTIPHON_TEST_PIDFILE": pidfile}
            with patch.dict(os.environ, env):
                antiphon._bounded_identity_probe(argv, os.getcwd())
            deadline = time.monotonic() + 3
            grandchild = None
            while time.monotonic() < deadline:
                try:
                    with open(pidfile, encoding="utf-8") as stream:
                        raw = stream.read().strip()
                    if raw:
                        grandchild = int(raw)
                        break
                except (OSError, ValueError):
                    pass
                time.sleep(0.05)
            self.assertIsNotNone(grandchild,
                                 "the fixture never produced a descendant, so "
                                 "it would measure nothing")
            deadline = time.monotonic() + 3
            alive = True
            while time.monotonic() < deadline:
                try:
                    os.kill(grandchild, 0)
                except ProcessLookupError:
                    alive = False
                    break
                time.sleep(0.05)
            if alive:
                with contextlib.suppress(ProcessLookupError):
                    os.kill(grandchild, signal.SIGKILL)
            self.assertFalse(alive,
                             "isolation promises descendant death; a leader "
                             "that exits must not take the group with it")
